 5: namespace App\Http\Controllers\Api\V1\Admin;
 6: 
 7: use App\Http\Controllers\Controller;
 8: use App\Http\Requests\Admin\Shipping\ShippingZoneRequest;
 9: use App\Http\Resources\Admin\ShippingZoneResource;
10: use App\Models\ShippingZone;
11: use Illuminate\Http\JsonResponse;
12: use Illuminate\Http\Resources\Json\AnonymousResourceCollection;
13: use Illuminate\Routing\Controllers\HasMiddleware;
14: use Illuminate\Routing\Controllers\Middleware;
15: 
16: /** إدارة مناطق الشحن ومدنها. */
17: class ShippingZoneController extends Controller implements HasMiddleware
18: {
19:     public static function middleware(): array
20:     {
21:         return [
22:             new Middleware('can:shipping.view', only: ['index', 'show']),
23:             new Middleware('can:shipping.create', only: ['store']),
24:             new Middleware('can:shipping.update', only: ['update']),
25:             new Middleware('can:shipping.delete', only: ['destroy']),
26:         ];
27:     }
28: 
29:     public function index(): AnonymousResourceCollection
30:     {
31:         return ShippingZoneResource::collection(
32:             ShippingZone::query()->with('cities')->latest('id')->paginate(20)
33:         );
34:     }
35: 
36:     public function store(ShippingZoneRequest $request): JsonResponse
37:     {
38:         $data = $request->validated();
39:         $zone = ShippingZone::create($data);
40:         $zone->cities()->sync($data['city_ids'] ?? []);
41: 
42:         return ShippingZoneResource::make($zone->load('cities'))->response()->setStatusCode(201);
43:     }
44: 
45:     public function show(ShippingZone $shippingZone): ShippingZoneResource
46:     {
47:         return ShippingZoneResource::make($shippingZone->load('cities'));
48:     }
49: 
50:     public function update(ShippingZoneRequest $request, ShippingZone $shippingZone): ShippingZoneResource
51:     {
52:         $data = $request->validated();
53:         $shippingZone->update($data);
54:         if (array_key_exists('city_ids', $data)) {
55:             $shippingZone->cities()->sync($data['city_ids'] ?? []);
56:         }
57: 
58:         return ShippingZoneResource::make($shippingZone->load('cities'));
59:     }
60: 
61:     public function destroy(ShippingZone $shippingZone): JsonResponse
62:     {
63:         $shippingZone->delete();
64: 
65:         return response()->json(['message' => 'تم حذف منطقة الشحن']);
66:     }
67: } 1: <?php
