 5: namespace App\Http\Controllers\Api\V1\Webhook;
 6: 
 7: use App\Http\Controllers\Controller;
 8: use App\Services\PaymentWebhookService;
 9: use Illuminate\Http\JsonResponse;
10: use Illuminate\Http\Request;
11: 
12: /**
13:  * ويب هوك بوابات الدفع — بلا مصادقة Sanctum؛ الحماية بالتوقيع
14:  * الرقمي HMAC والتسجيل المسبق في webhook_logs (Idempotency).
15:  */
16: class PaymentWebhookController extends Controller
17: {
18:     public function __construct(private readonly PaymentWebhookService $webhooks) {}
19: 
20:     public function handle(Request $request, string $gateway): JsonResponse
21:     {
22:         $header = (string) (config("webhooks.payment.{$gateway}.signature_header") ?? 'X-Webhook-Signature');
23:         $payload = json_decode($request->getContent(), true);
24:         $result = $this->webhooks->handle(
25:             $gateway,
26:             is_array($payload) ? $payload : [],
27:             $request->getContent(),
28:             $request->header($header),
29:             $request->ip(),
30:         );
31: 
32:         return response()->json($result['body'], $result['http']);
33:     }
34: } 1: <?php
