20:     public function handle(Request $request, string $company): JsonResponse
21:     {
22:         $header = (string) (config('webhooks.shipping.signature_header') ?? 'X-Webhook-Signature');
23:         $payload = json_decode($request->getContent(), true);
24:         $result = $this->webhooks->handle(
25:             $company,
26:             is_array($payload) ? $payload : [],
27:             $request->getContent(),
28:             $request->header($header),
29:             $request->ip(),
30:         );
31: 
32:         return response()->json($result['body'], $result['http']);
33:     }
34: } 1: <?php
