10: /** تمثيل طلب للعميل (إتمام شراء / طلبات الحساب). */
11: class OrderResource extends JsonResource
12: {
13:     /** @return array<string, mixed> */
14:     public function toArray(Request $request): array
15:     {
16:         return [
17:             'id' => $this->id,
18:             'order_number' => $this->order_number,
19:             'channel' => $this->channel,
20:             'status' => $this->status,
21:             'payment_method' => $this->payment_method,
22:             'payment_status' => $this->payment_status,
23:             'recipient_name' => $this->guest_name,
