 5: namespace App\Services;
 6: 
 7: use App\Models\City;
 8: use App\Models\ShippingRate;
 9: 
10: /**
11:  * تسعيرة الشحن التي يدفعها العميل (مصدر موحد مع تكلفة البوليصة — M12):
12:  * أول شركة نشطة (بترتيب id) لها سعر منطبق على المدينة؛ عند بلوغ حد الشحن
13:  * المجاني تكون التكلفة صفرًا، ورسوم الدفع عند الاستلام من نفس السعر.
14:  * بلا أي سعر منطبق: رجوع لسعر المدينة الافتراضي بلا رسوم COD.
15:  */
16: class ShippingQuoteService
17: {
18:     /** @return array{cost: float, cod_fee: float, rate: ShippingRate|null} */
19:     public function quoteForCity(int $cityId, float $merchandiseTotal, bool $cod): array
20:     {
21:         $rate = ShippingRate::query()
22:             ->join('shipping_zones', 'shipping_zones.id', '=', 'shipping_rates.shipping_zone_id')
23:             ->join('shipping_zone_cities', 'shipping_zone_cities.shipping_zone_id', '=', 'shipping_zones.id')
24:             ->join('shipping_companies', 'shipping_companies.id', '=', 'shipping_rates.shipping_company_id')
25:             ->where('shipping_zone_cities.city_id', $cityId)
26:             ->where('shipping_zones.is_active', true)
27:             ->where('shipping_companies.is_active', true)
28:             ->orderBy('shipping_companies.id')
29:             ->orderBy('shipping_rates.id')
30:             ->select('shipping_rates.*')
31:             ->first();
32: 
33:         if ($rate === null) {
34:             $city = City::query()->find($cityId);
35: 
36:             return ['cost' => (float) ($city?->shipping_cost ?? 0), 'cod_fee' => 0.0, 'rate' => null];
37:         }
38: 
39:         $free = $rate->free_shipping_threshold !== null
40:             && $merchandiseTotal >= (float) $rate->free_shipping_threshold;
41: 
42:         return [
43:             'cost' => $free ? 0.0 : (float) $rate->base_cost,
44:             'cod_fee' => $cod ? (float) $rate->cod_fee : 0.0,
45:             'rate' => $rate,
46:         ];
47:     }
48: } 1: <?php
