 5: namespace App\Services;
 6: 
 7: /**
 8:  * التحقق من توقيع الويب هوك: HMAC-SHA256 لنص الطلب الخام بسر المزود،
 9:  * بمقارنة آمنة ضد التوقيت. يقبل بادئة "sha256=" الاختيارية.
10:  */
11: class WebhookSignatureVerifier
12: {
13:     public function verify(?string $secret, string $rawBody, ?string $signature): bool
14:     {
15:         if ($secret === null || $secret === '' || $signature === null || $signature === '') {
16:             return false;
17:         }
18: 
19:         if (str_starts_with($signature, 'sha256=')) {
20:             $signature = substr($signature, 7);
21:         }
22: 
23:         $expected = hash_hmac('sha256', $rawBody, $secret);
24: 
25:         return hash_equals($expected, strtolower(trim($signature)));
26:     }
27: } 1: <?php
