 41: 
 42:     private Branch $branch;
 43: 
 44:     protected function setUp(): void
 45:     {
 46:         parent::setUp();
 47:         $this->seed(SettingSeeder::class);
 48:         $this->seed(RolePermissionSeeder::class);
 49:         $this->seed(PromotionPermissionSeeder::class);
 50:         $this->seed(ShippingPermissionSeeder::class);
 51:         $this->staff = User::factory()->create();
 52:         $this->staff->assignRole('Super Admin');
 53:         $this->branch = Branch::factory()->create();
 54:     }
 55: 
 56:     private function purchasableVariant(float $price = 100): ProductVariant
 57:     {
 58:         $product = Product::factory()->create(['status' => 'published']);
 59:         $variant = $product->variants()->first() ?? $product->variants()->create([
 60:             'name_ar' => 'قياسي', 'sku' => 'SKU-'.uniqid(), 'retail_price' => $price, 'is_active' => true,
 61:         ]);
 62:         if ($variant->retail_price === null) {
 63:             $variant->update(['retail_price' => $price]);
 64:         }
 65: 
 66:         return $variant;
 67:     }
 68: 
 69:     private function giveStock(ProductVariant $variant, float $qty): StockLevel
 70:     {
 71:         $location = Location::factory()->create(['branch_id' => $this->branch->id]);
 72: 
 73:         return StockLevel::query()->create([
 74:             'branch_id' => $this->branch->id, 'location_id' => $location->id,
 75:             'product_variant_id' => $variant->id, 'on_hand' => $qty, 'reserved' => 0,
 76:         ]);
 77:     }
 78: 
 79:     private function guestCheckout(ProductVariant $variant, float $qty, ?City $city = null, string $payment = 'cod'): Order
 80:     {
 81:         $city ??= City::factory()->create(['shipping_cost' => 0]);
 82:         $token = $this->postJson('/api/v1/store/cart/items', [
 83:             'product_variant_id' => $variant->id, 'qty' => $qty,
 84:         ])->assertOk()->json('data.cart_token');
 85:         $id = $this->withHeaders(['X-Cart-Session' => $token])->postJson('/api/v1/store/checkout', [
 86:             'recipient_name' => 'ضيف', 'recipient_phone' => '01012345678',
 87:             'city_id' => $city->id, 'shipping_address_line' => 'عنوان', 'payment_method' => $payment,
 88:         ])->assertCreated()->json('data.id');
 89: 
 90:         return Order::findOrFail($id);
 91:     }
 92: 
 93:     private function shipCodOrder(): array
 94:     {
 95:         $variant = $this->purchasableVariant(100);
 96:         $level = $this->giveStock($variant, 10);
 97:         $order = $this->guestCheckout($variant, 3);
 98:         app(OrderService::class)->changeStatus($order, OrderStatus::Confirmed, $this->staff);
 99:         $company = ShippingCompany::factory()->create([
100:             'code' => 'SHIPX', 'api_credentials' => ['webhook_secret' => 'ship-secret'],
101:         ]);
102:         $shipment = app(ShipmentService::class)->createForOrder($order->fresh(), $company->id, null, $this->staff);
103: 
104:         return [$order->fresh(), $shipment, $level, $variant];
105:     }
106: 
107:     private function shippingWebhook(Shipment $shipment, string $status, string $eventId): void
108:     {
109:         $body = json_encode([
110:             'event_id' => $eventId, 'awb' => $shipment->awb_number, 'status' => $status,
111:         ]);
112:         $this->call('POST', '/api/v1/webhooks/shipping/SHIPX', [], [], [],
113:             ['CONTENT_TYPE' => 'application/json',
114:                 'HTTP_X_WEBHOOK_SIGNATURE' => hash_hmac('sha256', (string) $body, 'ship-secret')], (string) $body)
115:             ->assertOk();
116:     }
