120:     public function test_returned_shipment_returns_order_and_restocks(): void
121:     {
122:         [$order, $shipment, $level, $variant] = $this->shipCodOrder();
123:         $this->assertSame('7.0000', (string) $level->fresh()->on_hand);
124:         $this->assertSame(3, (int) $variant->product->fresh()->sales_count);
125: 
126:         $this->shippingWebhook($shipment, 'returned', 'evt-ret-1');
127: 
128:         $this->assertSame(OrderStatus::Returned, $order->fresh()->status);
129:         $this->assertSame('10.0000', (string) $level->fresh()->on_hand);
130:         $this->assertSame(0, (int) $variant->product->fresh()->sales_count);
131:         $this->assertTrue(StockMovement::query()
132:             ->where('reference_id', $order->id)->where('type', StockMovementType::SaleReturn)->exists());
133:         // مرتجع لم يُسلَّم فعليًا: لا تحصيل COD
134:         $this->assertSame('unpaid', $order->fresh()->payment_status);
135:     }
