143:         $company = ShippingCompany::factory()->create([
144:             'code' => 'SHIPX', 'api_credentials' => ['webhook_secret' => 'ship-secret'],
145:         ]);
146:         $shipment = Shipment::factory()->create([
147:             'order_id' => $order->id, 'shipping_company_id' => $company->id, 'status' => 'created',
148:         ]);
149: 
150:         $this->shippingWebhook($shipment, 'delivered', 'evt-del-cancelled');
151: 
