158:     public function test_cancelling_order_reverses_coupon_usage_so_customer_can_reuse_it(): void
159:     {
160:         $variant = $this->purchasableVariant(100);
161:         $this->giveStock($variant, 10);
162:         Coupon::factory()->create(['code' => 'ONCE', 'type' => 'fixed', 'value' => 10, 'usage_limit_per_customer' => 1]);
163:         $customer = Customer::factory()->create();
164:         $token = $customer->createToken('t')->plainTextToken;
165:         $city = City::factory()->create(['shipping_cost' => 0]);
166: 
167:         $buy = function () use ($token, $variant, $city): int {
168:             $this->withToken($token)->postJson('/api/v1/store/cart/items', [
169:                 'product_variant_id' => $variant->id, 'qty' => 1,
170:             ])->assertOk();
171:             $this->withToken($token)->postJson('/api/v1/store/cart/coupon', ['code' => 'ONCE'])->assertOk();
172: 
173:             return $this->withToken($token)->postJson('/api/v1/store/checkout', [
174:                 'city_id' => $city->id, 'shipping_address_line' => 'عنوان', 'payment_method' => 'cod',
175:             ])->assertCreated()->json('data.id');
176:         };
177: 
178:         $orderId = $buy();
179:         $coupon = Coupon::where('code', 'ONCE')->first();
180:         $this->assertSame(1, (int) $coupon->used_count);
181:         $this->assertSame(1, $coupon->usages()->count());
182: 
183:         $this->withToken($token)->postJson("/api/v1/store/account/orders/{$orderId}/cancel")->assertOk();
184: 
185:         $this->assertSame(0, (int) $coupon->fresh()->used_count);
186:         $this->assertSame(0, $coupon->usages()->count());
187: 
188:         // الكوبون صالح للاستخدام من جديد بعد الإلغاء
189:         $this->assertNotNull($buy());
190:         $this->assertSame(1, (int) $coupon->fresh()->used_count);
