 31:  * webhook_logs، عدم تكرار المعالجة، وتأثيرات الطلب التلقائية.
 32:  */
 33: class WebhookTest extends TestCase
 34: {
 35:     use LazilyRefreshDatabase;
 36: 
 37:     private const PAY_SECRET = 'pay-secret';
 38: 
 39:     private const SHIP_SECRET = 'ship-secret';
 40: 
 41:     private User $staff;
 42: 
 43:     private Branch $branch;
 44: 
 45:     protected function setUp(): void
 46:     {
 47:         parent::setUp();
 48:         $this->seed(SettingSeeder::class);
 49:         config(['webhooks.payment.testpay' => [
 50:             'secret' => self::PAY_SECRET,
 51:             'signature_header' => 'X-Webhook-Signature',
 52:         ]]);
 53:         $this->staff = User::factory()->create();
 54:         // منفّذ نظام: تأكيد الويب هوك بلا فاعل موظف — يسقط على أول Super Admin
 55:         $superAdmin = User::factory()->create();
 56:         $superAdmin->assignRole(Role::findOrCreate('Super Admin', 'staff'));
 57:         $this->branch = Branch::factory()->create();
 58:     }
 59: 
 60:     public function test_payment_success_marks_paid_confirms_and_allocates(): void
 61:     {
 62:         $variant = $this->purchasableVariant(100);
 63:         $this->giveStock($variant, 10);
 64:         $order = $this->makeOrder($variant, 2, 'card');
 65:         $this->assertSame(OrderStatus::Pending, $order->status);
 66: 
 67:         $this->postWebhook('/api/v1/webhooks/payment/testpay', [
 68:             'event_id' => 'evt_1', 'order_number' => $order->order_number, 'status' => 'paid',
 69:         ], self::PAY_SECRET)->assertOk()->assertJsonPath('received', true);
 70: 
 71:         $order = $order->fresh();
 72:         $this->assertSame('paid', $order->payment_status);
 73:         $this->assertSame(OrderStatus::Confirmed, $order->status);
 74:         $this->assertSame($this->branch->id, $order->allocated_branch_id);
 75:         $this->assertSame('2.0000', (string) $this->level($variant->id)->reserved);
 76:         $this->assertSame('processed', WebhookLog::query()->sole()->status);
 77:         $this->assertTrue(WebhookLog::query()->sole()->signature_valid);
 78:     }
