 96:     public function test_payment_webhook_duplicate_event_is_not_reprocessed(): void
 97:     {
 98:         $variant = $this->purchasableVariant(100);
 99:         $this->giveStock($variant, 10);
100:         $order = $this->makeOrder($variant, 2, 'card');
101:         $payload = ['event_id' => 'evt_dup', 'order_number' => $order->order_number, 'status' => 'paid'];
102: 
103:         $this->postWebhook('/api/v1/webhooks/payment/testpay', $payload, self::PAY_SECRET)->assertOk();
104:         $histories = $order->statusHistories()->count();
105:         $movements = StockMovement::query()->where('type', StockMovementType::Reserve)->count();
106: 
107:         $this->postWebhook('/api/v1/webhooks/payment/testpay', $payload, self::PAY_SECRET)
108:             ->assertOk()->assertJsonPath('duplicate', true);
109: 
110:         $this->assertSame($histories, $order->statusHistories()->count());
111:         $this->assertSame($movements, StockMovement::query()->where('type', StockMovementType::Reserve)->count());
112:         $this->assertSame('2.0000', (string) $this->level($variant->id)->reserved);
113:         $this->assertSame('duplicate', WebhookLog::query()->latest('id')->first()->status);
114:     }
115: 
116:     public function test_payment_failed_keeps_order_pending_and_unknown_gateway_404(): void
117:     {
118:         $variant = $this->purchasableVariant(100);
119:         $this->giveStock($variant, 5);
120:         $order = $this->makeOrder($variant, 1, 'card');
121: 
122:         $this->postWebhook('/api/v1/webhooks/payment/testpay', [
123:             'event_id' => 'evt_fail', 'order_number' => $order->order_number, 'status' => 'failed',
124:         ], self::PAY_SECRET)->assertOk();
125: 
126:         $order = $order->fresh();
127:         $this->assertSame('failed', $order->payment_status);
128:         $this->assertSame(OrderStatus::Pending, $order->status);
129: 
130:         $this->postWebhook('/api/v1/webhooks/payment/nosuch', [
131:             'order_number' => $order->order_number, 'status' => 'paid',
132:         ], self::PAY_SECRET)->assertNotFound();
133:     }
