135:     public function test_shipping_delivered_webhook_delivers_order_and_settles_cod(): void
136:     {
137:         $variant = $this->purchasableVariant(100);
138:         $this->giveStock($variant, 5);
139:         $order = $this->makeOrder($variant, 1, 'cod');
140:         app(OrderService::class)->changeStatus($order, OrderStatus::Confirmed, $this->staff);
141: 
142:         $company = ShippingCompany::factory()->create([
143:             'code' => 'bosta',
144:             'api_credentials' => ['webhook_secret' => self::SHIP_SECRET],
145:         ]);
146:         app(ShipmentService::class)->createForOrder($order, $company->id, 'BOSTA-123', $this->staff);
147:         $this->assertSame(OrderStatus::Shipped, $order->fresh()->status);
148: 
149:         $this->postWebhook('/api/v1/webhooks/shipping/bosta', [
150:             'event_id' => 'ev_ship_1', 'awb_number' => 'BOSTA-123', 'status' => 'delivered',
151:         ], self::SHIP_SECRET)->assertOk()->assertJsonPath('received', true);
152: 
153:         $order = $order->fresh();
154:         $this->assertSame(OrderStatus::Delivered, $order->status);
155:         $this->assertSame('paid', $order->payment_status); // COD يُحصّل عند التسليم
156:         $this->assertSame('delivered', $order->shipments()->sole()->status->value);
157:     }
