159:     public function test_shipping_webhook_unknown_awb_and_bad_signature(): void
160:     {
161:         ShippingCompany::factory()->create([
162:             'code' => 'bosta',
163:             'api_credentials' => ['webhook_secret' => self::SHIP_SECRET],
164:         ]);
165: 
166:         $this->postWebhook('/api/v1/webhooks/shipping/bosta', [
167:             'event_id' => 'ev_x', 'awb_number' => 'NOPE-1', 'status' => 'in_transit',
168:         ], self::SHIP_SECRET)->assertOk()->assertJsonPath('received', false);
169:         $this->assertSame('failed', WebhookLog::query()->sole()->status);
170: 
171:         $this->postWebhook('/api/v1/webhooks/shipping/bosta', [
172:             'event_id' => 'ev_y', 'awb_number' => 'NOPE-1', 'status' => 'delivered',
173:         ], 'bad')->assertForbidden();
174:     }
175: 
176:     // ---------- helpers ----------
177: 
178:     private function postWebhook(string $uri, array $payload, string $secret): TestResponse
179:     {
180:         $body = json_encode($payload);
181: 
182:         return $this->call('POST', $uri, [], [], [], [
183:             'HTTP_X-Webhook-Signature' => hash_hmac('sha256', $body, $secret),
184:             'CONTENT_TYPE' => 'application/json',
185:             'HTTP_ACCEPT' => 'application/json',
186:         ], $body);
187:     }
188: 
189:     private function makeOrder(ProductVariant $variant, float|int $qty, string $paymentMethod): Order
190:     {
191:         $cart = Cart::create([]);
192:         $cart->items()->create(['product_variant_id' => $variant->id, 'qty' => $qty]);
193: 
194:         return app(OrderService::class)->createFromCart($cart, [
195:             'recipient_name' => 'عميل', 'recipient_phone' => '01012345678',
196:             'payment_method' => $paymentMethod,
197:         ]);
198:     }
199: 
200:     private function purchasableVariant(float $price): ProductVariant
201:     {
202:         $product = Product::factory()->create(['status' => 'published']);
203: 
204:         return ProductVariant::factory()->create([
205:             'product_id' => $product->id,
206:             'retail_price' => $price,
207:         ]);
208:     }
209: 
210:     private function giveStock(ProductVariant $variant, float|int $qty): void
211:     {
212:         app(InventoryService::class)->recordMovement([
213:             'product_variant_id' => $variant->id,
214:             'branch_id' => $this->branch->id,
215:             'type' => StockMovementType::AdjustmentIn,
216:             'affected_bucket' => StockBucket::OnHand,
217:             'quantity' => $qty,
218:             'created_by' => $this->staff->id,
219:         ]);
220:     }
221: 
222:     private function level(int $variantId): StockLevel
223:     {
224:         return StockLevel::query()
225:             ->where('product_variant_id', $variantId)
226:             ->where('branch_id', $this->branch->id)
227:             ->whereNull('location_id')
228:             ->firstOrFail();
229:     }
230: } 1: <?php
