48:     {
49:         $data = $request->validated();
50:         // الأسرار لا تُرجع في الردود (has_api_credentials فقط)، فشاشة التعديل
51:         // ترسل null — تُتجاهل ولا تمحو الأسرار المحفوظة (M10)
52:         if (array_key_exists('api_credentials', $data) && $data['api_credentials'] === null) {
53:             unset($data['api_credentials']);
54:         }
55:         $shippingCompany->update($data);
56: 
57:         return ShippingCompanyResource::make($shippingCompany);
