60:     public function destroy(ShippingCompany $shippingCompany): JsonResponse
61:     {
62:         // شركة لها بوليصات: الحذف يكسر FK — يُمنع ويُعطَّل بدلًا منه (M9)
63:         if ($shippingCompany->shipments()->exists()) {
64:             throw new BusinessException('لا يمكن حذف شركة شحن لها بوليصات مسجلة؛ عطّلها بدلًا من حذفها.');
65:         }
66:         $shippingCompany->delete();
67: 
68:         return response()->json(['message' => 'تم حذف شركة الشحن']);
69:     }
70: } 1: <?php
