40:         // الدفع الآجل (credit) لعملاء الجملة/التوزيع المعتمدين فقط
41:         $user = auth('sanctum')->user();
42:         if ($user instanceof Customer
43:             && $user->status === CustomerStatus::Approved
44:             && in_array($user->type, [CustomerType::Wholesale, CustomerType::Distributor], true)) {
45:             $methods[] = 'credit';
46:         }
47: 
48:         return array_values(array_unique($methods));
