 92:         $city = City::factory()->create(['name_ar' => 'القاهرة']);
 93:         $order = $this->makeOrder([[$variant, 3]], cityId: $city->id);
 94: 
 95:         $allocated = app(OrderAllocationService::class)->allocate($order, performedBy: $this->staff->id);
