  5: namespace App\Http\Controllers\Api\V1\Admin;
  6: 
  7: use App\Enums\OrderStatus;
  8: use App\Exceptions\BusinessException;
  9: use App\Http\Controllers\Controller;
 10: use App\Http\Requests\Admin\Order\AllocateOrderRequest;
 11: use App\Http\Requests\Admin\Order\CreateShipmentRequest;
 12: use App\Http\Requests\Admin\Order\UpdateOrderStatusRequest;
 13: use App\Http\Resources\Admin\AdminOrderResource;
 14: use App\Http\Resources\Admin\ShipmentResource;
 15: use App\Models\Order;
 16: use App\Services\OrderAllocationService;
 17: use App\Services\OrderService;
 18: use App\Services\ShipmentService;
 19: use Illuminate\Http\Request;
 20: use Illuminate\Http\Resources\Json\AnonymousResourceCollection;
 21: use Illuminate\Routing\Controllers\HasMiddleware;
 22: use Illuminate\Routing\Controllers\Middleware;
 23: use Illuminate\Support\Carbon;
 24: use Illuminate\Validation\Rule;
 25: 
 26: /** إدارة الطلبات: عرض وفلترة، تغيير الحالة عبر OrderService، وتوزيع يدوي/مُجبر. */
 27: class OrderController extends Controller implements HasMiddleware
 28: {
 29:     public function __construct(
 30:         private readonly OrderService $orders,
 31:         private readonly OrderAllocationService $allocation,
 32:         private readonly ShipmentService $shipments,
 33:     ) {}
 34: 
 35:     public static function middleware(): array
 36:     {
 37:         return [
 38:             new Middleware('can:orders.view', only: ['index', 'show']),
 39:             new Middleware('can:orders.update', only: ['updateStatus', 'createShipment']),
 40:             new Middleware('can:orders.allocate', only: ['allocate']),
 41:         ];
 42:     }
 43: 
 44:     public function index(Request $request): AnonymousResourceCollection
 45:     {
 46:         $filters = $request->validate([
 47:             'status' => ['nullable', Rule::in(array_column(OrderStatus::cases(), 'value'))],
 48:             'allocated_branch_id' => ['nullable', 'integer', 'min:1'],
 49:             'payment_method' => ['nullable', Rule::in(['cod', 'card', 'wallet', 'bank_transfer', 'credit'])],
 50:             'date_from' => ['nullable', 'date'],
 51:             'date_to' => ['nullable', 'date'],
 52:             'search' => ['nullable', 'string', 'max:100'],
 53:         ]);
 54: 
 55:         $orders = Order::query()
 56:             ->with(['customer', 'allocatedBranch'])
 57:             ->withCount('items')
 58:             ->when($filters['status'] ?? null, fn ($q, $status) => $q->where('status', $status))
 59:             ->when($filters['allocated_branch_id'] ?? null, fn ($q, $branchId) => $q->where('allocated_branch_id', $branchId))
 60:             ->when($filters['payment_method'] ?? null, fn ($q, $method) => $q->where('payment_method', $method))
 61:             // نطاق زمني بدل whereDate حتى يعمل فهرس created_at (M16)،
 62:             // بمنطقة العمل ثم يُخزّن/يُقارن بـ UTC
 63:             ->when($filters['date_from'] ?? null, fn ($q, $date) => $q->where('created_at', '>=',
 64:                 Carbon::parse($date, (string) config('app.business_timezone'))->startOfDay()->utc()))
 65:             ->when($filters['date_to'] ?? null, fn ($q, $date) => $q->where('created_at', '<',
 66:                 Carbon::parse($date, (string) config('app.business_timezone'))->startOfDay()->addDay()->utc()))
 67:             // بحث: رقم الطلب والهاتف بالبادئة (يستخدم الفهارس)، والاسم
 68:             // بالاحتواء مع تهريب محارف LIKE من مدخل المستخدم (M16)
 69:             ->when($filters['search'] ?? null, fn ($q, $term) => $q->where(function ($inner) use ($term): void {
 70:                 $escaped = str_replace(['\\', '%', '_'], ['\\\\', '\\%', '\\_'], (string) $term);
 71:                 $inner->where('order_number', 'like', $escaped.'%')
 72:                     ->orWhere('guest_phone', 'like', $escaped.'%')
 73:                     ->orWhere('guest_name', 'like', '%'.$escaped.'%');
 74:             }))
 75:             ->latest('id')
 76:             ->paginate(20);
 77: 
 78:         return AdminOrderResource::collection($orders);
 79:     }
 80: 
 81:     public function show(Order $order): AdminOrderResource
 82:     {
 83:         return AdminOrderResource::make(
 84:             $order->load(['items', 'statusHistories', 'customer', 'city', 'allocatedBranch'])
 85:         );
 86:     }
 87: 
 88:     public function updateStatus(UpdateOrderStatusRequest $request, Order $order): AdminOrderResource
 89:     {
 90:         // الشحن له بوليصة ومسار مخزون: من إنشاء البوليصة فقط (L3) —
 91:         // وضع Shipped يدويًا يترك الطلب بلا بوليصة فلا يصله ويب هوك تسليم
 92:         if (($request->validated()['status'] ?? null) === OrderStatus::Shipped->value) {
 93:             throw new BusinessException('حالة الشحن تتم فقط عبر إنشاء بوليصة شحن للطلب.');
 94:         }
 95: 
 96:         $order = $this->orders->changeStatus(
 97:             $order,
 98:             (string) $request->validated()['status'],
 99:             $request->user(),
100:             $request->validated()['notes'] ?? null,
101:         );
102: 
103:         return AdminOrderResource::make(
104:             $order->load(['items', 'statusHistories', 'customer', 'city', 'allocatedBranch'])
105:         );
106:     }
107: 
108:     /** إنشاء بوليصة شحن للطلب وتحويله إلى SHIPPED عبر OrderService. */
