  7: use App\Enums\OrderStatus;
  8: use App\Exceptions\BusinessException;
  9: use App\Models\Cart;
 10: use App\Models\Coupon;
 11: use App\Models\CouponUsage;
 12: use App\Models\Customer;
 13: use App\Models\Order;
 14: 
 15: /**
 16:  * التحقق من الكوبونات وربطها بالسلة وحساب خصمها وتسجيل استخدامها.
 17:  * الفحوص: التفعيل، النافذة الزمنية، الحد الكلي للاستخدام، حد العميل
 18:  * الواحد (usage_limit_per_customer — افتراضي 1)، والحد الأدنى للسلة.
 19:  * الخصم النسبي: min(subtotal × value/100, max_discount_amount).
 20:  * كوبون free_shipping خصمه المالي على البضاعة صفر — أثره إلغاء الشحن
 21:  * عند إتمام الشراء (يُسجل مبلغ الشحن المُعفى في سجل الاستخدام).
 22:  */
 23: class CouponService
 24: {
 25:     public function validateAndApply(Cart $cart, string $code, float $subtotal, ?Customer $customer = null): float
 26:     {
 27:         $coupon = $this->findRedeemable($code, $subtotal, $customer);
 28: 
 29:         $cart->update(['coupon_id' => $coupon->id]);
 30: 
 31:         return $this->discountFor($coupon, $subtotal);
 32:     }
 33: 
 34:     /** يتحقق من كوبون مرتبط بسلة (عند إتمام الشراء) ويرجعه أو يرمي استثناءً. */
 35:     public function redeemableById(int $couponId, float $subtotal, ?Customer $customer = null, ?string $guestPhone = null): Coupon
 36:     {
 37:         $coupon = Coupon::query()->find($couponId);
 38:         if ($coupon === null) {
 39:             throw new BusinessException('الكوبون المرتبط بالسلة لم يعد موجودًا.');
 40:         }
 41:         $this->assertRedeemable($coupon, $subtotal, $customer, $guestPhone);
 42: 
 43:         return $coupon;
 44:     }
 45: 
 46:     /** خصم البضاعة: النسبي بسقف، والثابت بحد الإجمالي، والشحن المجاني صفر هنا. */
 47:     public function discountFor(Coupon $coupon, float $subtotal): float
 48:     {
 49:         if ($subtotal <= 0 || $coupon->type === 'free_shipping') {
 50:             return 0.0;
 51:         }
 52: 
 53:         $discount = $coupon->type === 'percentage'
 54:             ? $subtotal * (float) $coupon->value / 100
 55:             : (float) $coupon->value;
 56: 
 57:         if ($coupon->max_discount_amount !== null) {
 58:             $discount = min($discount, (float) $coupon->max_discount_amount);
 59:         }
 60: 
 61:         return round(min($discount, $subtotal), 2);
 62:     }
 63: 
 64:     /** تسجيل استخدام فعلي عند إتمام الطلب + تحديث العداد الكلي. */
 65:     public function recordUsage(Coupon $coupon, Order $order, ?Customer $customer, float $discountAmount): CouponUsage
 66:     {
 67:         $usage = CouponUsage::create([
 68:             'coupon_id' => $coupon->id,
 69:             'customer_id' => $customer?->id,
 70:             'order_id' => $order->id,
 71:             'discount_amount' => $discountAmount,
 72:         ]);
 73:         $coupon->increment('used_count');
 74: 
 75:         return $usage;
 76:     }
 77: 
 78:     private function findRedeemable(string $code, float $subtotal, ?Customer $customer): Coupon
 79:     {
 80:         $coupon = Coupon::query()->where('code', strtoupper(trim($code)))->first();
 81:         if ($coupon === null) {
 82:             throw new BusinessException('كود الخصم غير صحيح.');
 83:         }
 84:         $this->assertRedeemable($coupon, $subtotal, $customer);
 85: 
 86:         return $coupon;
 87:     }
 88: 
 89:     private function assertRedeemable(Coupon $coupon, float $subtotal, ?Customer $customer, ?string $guestPhone = null): void
 90:     {
 91:         if (! $coupon->isRedeemableNow()) {
 92:             throw new BusinessException('كود الخصم غير متاح أو انتهت صلاحيته أو استُنفد حد استخدامه.');
 93:         }
 94:         if ($coupon->min_order_amount !== null && $subtotal < (float) $coupon->min_order_amount) {
 95:             throw new BusinessException('قيمة السلة أقل من الحد الأدنى لاستخدام هذا الكوبون.');
 96:         }
 97:         if ((int) $coupon->usage_limit_per_customer <= 0) {
 98:             return;
 99:         }
100:         if ($customer !== null) {
101:             // استخدامات العميل المسجل — الطلبات الملغاة لا تحتسب
102:             $usedByCustomer = $coupon->usages()
103:                 ->where('customer_id', $customer->id)
104:                 ->whereHas('order', fn ($q) => $q->where('status', '!=', OrderStatus::Cancelled->value))
105:                 ->count();
106:             if ($usedByCustomer >= (int) $coupon->usage_limit_per_customer) {
107:                 throw new BusinessException('وصلت لحد استخدام هذا الكوبون لحسابك.');
108:             }
109:         } elseif ($guestPhone !== null && trim($guestPhone) !== '') {
110:             // هوية الزائر هي رقم هاتفه الموحد الصيغة — تبديل cart_token لا يتجاوز الحد (H3)
111:             $normalized = Customer::normalizePhone($guestPhone);
112:             $usedByPhone = $coupon->usages()
113:                 ->join('orders', 'orders.id', '=', 'coupon_usages.order_id')
114:                 ->where('orders.status', '!=', OrderStatus::Cancelled->value)
115:                 ->whereNotNull('orders.guest_phone')
116:                 ->pluck('orders.guest_phone')
117:                 ->filter(fn ($phone): bool => Customer::normalizePhone((string) $phone) === $normalized)
118:                 ->count();
119:             if ($usedByPhone >= (int) $coupon->usage_limit_per_customer) {
120:                 throw new BusinessException('وصلت لحد استخدام هذا الكوبون لرقم هاتفك.');
121:             }
122:         }
123:     }
124: }  1: <?php
