  5: namespace App\Services;
  6: 
  7: use App\Enums\StockBucket;
  8: use App\Enums\StockMovementType;
  9: use App\Exceptions\BusinessException;
 10: use App\Models\Branch;
 11: use App\Models\Order;
 12: use App\Models\OrderItem;
 13: use App\Models\StockLevel;
 14: use Illuminate\Database\Eloquent\Builder;
 15: use Illuminate\Support\Facades\DB;
 16: 
 17: /**
 18:  * توزيع الطلب على الفروع وحجز مخزونه (reserved) عبر InventoryService حصرًا.
 19:  *
 20:  * الخوارزمية:
 21:  * 1. فرع مُجبر من الأدمن: يُتحقق من تغطيته ويُحجز منه.
 22:  * 2. أول فرع نشط واحد يغطي الطلب كاملًا — أولوية لفرع نفس مدينة العميل.
 23:  * 3. وإلا: كل صنف من الفرع الأعلى رصيدًا متاحًا له (الصنف كاملًا من فرع واحد).
 24:  *
 25:  * داخل الفرع الواحد قد يتوزع الصنف على أكثر من موقع (الأعلى متاحًا أولًا).
 26:  * أي نقص في أي صنف يُلغي العملية كلها (transaction واحدة — لا حجز جزئي يتسرب).
 27:  */
 28: class OrderAllocationService
 29: {
 30:     public function __construct(protected InventoryService $inventoryService) {}
 31: 
 32:     public function allocate(Order $order, ?int $forcedBranchId = null, ?int $performedBy = null): Order
 33:     {
 34:         return DB::transaction(function () use ($order, $forcedBranchId, $performedBy): Order {
 35:             // إعادة قراءة الطلب بقفل صف قبل فحص التوزيع السابق (C1)
 36:             $order = Order::query()->lockForUpdate()->findOrFail($order->id);
 37:             $order->load('items');
 38:             $performedBy ??= auth()->id();
 39: 
 40:             if ($order->allocated_branch_id !== null
 41:                 || $order->items->contains(fn (OrderItem $item): bool => $item->allocated_branch_id !== null)) {
 42:                 throw new BusinessException('الطلب مُوزّع على الفروع من قبل؛ ألغِ التوزيع الحالي أولًا قبل إعادة التوزيع.');
 43:             }
 44: 
 45:             // 1. فرع مُجبر يدويًا
 46:             if ($forcedBranchId !== null) {
 47:                 $branch = Branch::query()->where('is_active', true)->find($forcedBranchId);
 48:                 if ($branch === null) {
 49:                     throw new BusinessException('الفرع المحدد غير موجود أو غير نشط.');
 50:                 }
 51:                 $this->reserveItemsFromBranch($order, $branch->id, $performedBy);
 52:                 $order->update(['allocated_branch_id' => $branch->id]);
 53: 
 54:                 return $order->fresh(['items']);
 55:             }
 56: 
 57:             // خريطة تغطية واحدة مجمّعة لكل الفروع والأصناف (M15) بدل
 58:             // استعلام لكل فرع × صنف — القرارات التالية كلها في الذاكرة
 59:             $coverage = $this->branchAvailabilityMap($order);
 60: 
 61:             // 2. فرع واحد يغطي الطلب كاملًا (أولوية لنفس مدينة العميل:
 62:             // بالمعرّف أولًا ثم بمطابقة الاسم كرجوع — L5)
 63:             $cityName = $order->city?->name_ar;
 64:             $branches = Branch::query()
 65:                 ->where('is_active', true)
 66:                 ->when($order->city_id !== null, fn (Builder $q): Builder => $q->orderByRaw('CASE WHEN city_id = ? THEN 0 ELSE 1 END', [$order->city_id]))
 67:                 ->when($cityName !== null, fn (Builder $q): Builder => $q->orderByRaw('city = ? DESC', [$cityName]))
 68:                 ->orderBy('id')
 69:                 ->get();
 70: 
 71:             foreach ($branches as $branch) {
 72:                 if ($this->canBranchFulfillFullOrder($order, $branch->id, $coverage)) {
 73:                     $this->reserveItemsFromBranch($order, $branch->id, $performedBy);
 74:                     $order->update(['allocated_branch_id' => $branch->id]);
 75: 
 76:                     return $order->fresh(['items']);
 77:                 }
 78:             }
 79: 
 80:             // 3. كل صنف من الفرع الأعلى رصيدًا متاحًا له
 81:             foreach ($order->items as $item) {
 82:                 $branchId = $this->bestBranchForItem($item, $coverage);
 83:                 if ($branchId === null) {
 84:                     throw new BusinessException("الرصيد المتاح غير كافٍ للصنف ({$item->sku_snapshot}) في أي فرع.");
 85:                 }
 86:                 $this->reserveItemFromBranch($order, $item, $branchId, $performedBy);
 87:                 $item->update(['allocated_branch_id' => $branchId]);
 88:             }
 89: 
 90:             return $order->fresh(['items']);
 91:         });
 92:     }
 93: 
 94:     /**
 95:      * تغطية الفروع لأصناف الطلب باستعلام واحد مجمّع (M15):
 96:      * ‏[branch_id][variant_id] => مجموع المتاح في المواقع النشطة.
 97:      *
 98:      * @return array<int, array<int, float>>
 99:      */
100:     private function branchAvailabilityMap(Order $order): array
101:     {
102:         $variantIds = $order->items
103:             ->map(fn (OrderItem $item): int => (int) $item->product_variant_id)
104:             ->unique()->values()->all();
105: 
106:         $rows = StockLevel::query()
107:             ->whereIn('product_variant_id', $variantIds)
108:             ->whereHas('branch', fn (Builder $q): Builder => $q->where('is_active', true))
109:             ->where(fn (Builder $q): Builder => $q
110:                 ->whereNull('location_id')
111:                 ->orWhereHas('location', fn (Builder $l): Builder => $l->where('is_active', true)))
112:             ->groupBy('branch_id', 'product_variant_id')
113:             ->selectRaw('branch_id, product_variant_id, SUM(available) as total_available')
114:             ->get();
115: 
116:         $map = [];
117:         foreach ($rows as $row) {
118:             $map[(int) $row->branch_id][(int) $row->product_variant_id] = (float) $row->total_available;
119:         }
120: 
121:         return $map;
122:     }
123: 
124:     /** @param array<int, array<int, float>> $coverage */
125:     private function canBranchFulfillFullOrder(Order $order, int $branchId, array $coverage): bool
126:     {
127:         foreach ($order->items as $item) {
128:             if (($coverage[$branchId][(int) $item->product_variant_id] ?? 0) < (float) $item->qty) {
129:                 return false;
130:             }
131:         }
132: 
133:         return true;
134:     }
135: 
136:     /** @param array<int, array<int, float>> $coverage */
137:     private function bestBranchForItem(OrderItem $item, array $coverage): ?int
138:     {
139:         $best = null;
140:         $bestAvailable = 0.0;
141:         foreach ($coverage as $branchId => $variants) {
142:             $available = $variants[(int) $item->product_variant_id] ?? 0;
143:             if ($available >= (float) $item->qty && $available > $bestAvailable) {
144:                 $best = $branchId;
145:                 $bestAvailable = $available;
146:             }
147:         }
148: 
149:         return $best;
150:     }
151: 
152:     private function reserveItemsFromBranch(Order $order, int $branchId, ?int $performedBy): void
153:     {
154:         foreach ($order->items as $item) {
155:             $this->reserveItemFromBranch($order, $item, $branchId, $performedBy);
156:             $item->update(['allocated_branch_id' => $branchId]);
157:         }
158:     }
159: 
160:     /**
161:      * حجز كمية الصنف من فرع واحد، موزعة على مواقعه الأعلى متاحًا عند الحاجة.
162:      */
163:     private function reserveItemFromBranch(Order $order, OrderItem $item, int $branchId, ?int $performedBy): void
164:     {
165:         $remaining = (float) $item->qty;
166:         // قفل صفوف الأرصدة بترتيب ثابت (id) حتى لا يُحجز نفس الرصيد مرتين (H10)
167:         $levels = $this->usableLevels((int) $item->product_variant_id, $branchId)
168:             ->where('available', '>', 0)
169:             ->orderBy('id')
170:             ->lockForUpdate()
171:             ->get();
172: 
173:         foreach ($levels as $level) {
174:             if ($remaining <= 0) {
175:                 break;
176:             }
177:             $take = min((float) $level->available, $remaining);
178:             $this->inventoryService->recordMovement([
179:                 'product_variant_id' => (int) $item->product_variant_id,
180:                 'branch_id' => $branchId,
181:                 'location_id' => $level->location_id,
182:                 'type' => StockMovementType::Reserve,
183:                 'affected_bucket' => StockBucket::Reserved,
184:                 'quantity' => $take,
185:                 'reference_type' => Order::class,
186:                 'reference_id' => $order->id,
187:                 'created_by' => $performedBy,
188:                 'notes' => "حجز للطلب رقم {$order->order_number}",
189:             ]);
190:             $remaining -= $take;
191:         }
192: 
193:         if ($remaining > 0) {
194:             throw new BusinessException("الفرع المحدد لا يمتلك كمية كافية من الصنف ({$item->sku_snapshot}).");
195:         }
196:     }
197: 
198:     /**
199:      * صفوف رصيد قابلة للاستخدام: رصيد الفرع/المتغير في مواقع نشطة
200:      * (أو بلا موقع) — الحجز لا يخرج من موقع معطّل.
201:      *
202:      * @return Builder<StockLevel>
203:      */
204:     private function usableLevels(int $variantId, ?int $branchId = null): Builder
205:     {
206:         return StockLevel::query()
207:             ->where('product_variant_id', $variantId)
208:             ->when($branchId !== null, fn (Builder $q): Builder => $q->where('branch_id', $branchId))
209:             ->where(fn (Builder $q): Builder => $q
210:                 ->whereNull('location_id')
211:                 ->orWhereHas('location', fn (Builder $l): Builder => $l->where('is_active', true)));
212:     }
213: }  1: <?php
