 18: /**
 19:  * إنشاء بوالص الشحن للطلبات.
 20:  * لا توجد بوابة شركة شحن مربوطة بعد: رقم البوليصة يُولّد داخليًا
 21:  * (أو يُمرّر جاهزًا من الأدمن)، وتكلفة البوليصة من جدول أسعار الشحن
 22:  * (شركة × منطقة مدينة الطلب) مع احترام حد الشحن المجاني.
 23:  */
 24: class ShipmentService
 25: {
 26:     public function __construct(protected OrderService $orders) {}
 27: 
 28:     public function createForOrder(Order $order, int $companyId, ?string $awbNumber, User $actor): Shipment
 29:     {
 30:         return DB::transaction(function () use ($order, $companyId, $awbNumber, $actor): Shipment {
 31:             // قفل الطلب والتحقق من حالته ومن عدم وجود بوليصة نشطة —
 32:             // نقرة مزدوجة لا تنتج بوليصتين ولا بيعًا مكررًا (H1)
 33:             $order = Order::query()->lockForUpdate()->findOrFail($order->id);
 34:             if (! in_array($order->status, [OrderStatus::Confirmed, OrderStatus::Processing], true)) {
 35:                 throw new BusinessException('لا يمكن إنشاء بوليصة إلا لطلب مؤكد أو قيد التجهيز.');
 36:             }
 37:             $hasActiveShipment = $order->shipments()
 38:                 ->whereNotIn('status', [ShipmentStatus::Failed->value, ShipmentStatus::Returned->value])
 39:                 ->exists();
 40:             if ($hasActiveShipment) {
 41:                 throw new BusinessException('توجد بوليصة نشطة لهذا الطلب بالفعل.');
 42:             }
 43: 
 44:             $company = ShippingCompany::query()->where('is_active', true)->find($companyId);
 45:             if ($company === null) {
 46:                 throw new BusinessException('شركة الشحن غير موجودة أو غير نشطة.');
 47:             }
 48: 
 49:             $rate = $this->rateFor($order, $company->id);
 50:             $shippingCost = $rate !== null ? (float) $rate->base_cost : (float) $order->shipping_cost;
 51:             if ($rate !== null && $rate->free_shipping_threshold !== null
 52:                 && ((float) $order->subtotal - (float) $order->discount_amount) >= (float) $rate->free_shipping_threshold) {
 53:                 $shippingCost = 0.0;
 54:             }
 55: 
 56:             $shipment = Shipment::create([
 57:                 'order_id' => $order->id,
 58:                 'shipping_company_id' => $company->id,
 59:                 'awb_number' => $awbNumber ?? $this->generateAwb($company),
 60:                 'status' => ShipmentStatus::Created,
 61:                 'label_url' => null,
 62:                 'shipping_cost' => $shippingCost,
 63:                 'cod_amount' => $order->payment_method === 'cod' ? (float) $order->grand_total : 0,
 64:                 'raw_response' => ['source' => 'internal'],
 65:             ]);
 66: 
 67:             // الشحن الفعلي للطلب (يفك الحجز ويخصم البيع) عبر بوابة الحالة
 68:             $this->orders->changeStatus($order, OrderStatus::Shipped, $actor, "تم إنشاء بوليصة الشحن {$shipment->awb_number}");
 69: 
 70:             return $shipment->fresh(['company', 'order']);
 71:         });
 72:     }
 73: 
 74:     /** سعر الشركة لمنطقة مدينة الطلب إن وُجد. */
 75:     /**
 76:      * سعر الشركة لمدينة الطلب: join مباشر rates × zone_cities مفلتر بالشركة
 77:      * والمدينة معًا — مدينة في أكثر من منطقة لا تختار منطقة بلا سعر (M12).
 78:      */
 79:     private function rateFor(Order $order, int $companyId): ?ShippingRate
 80:     {
 81:         if ($order->city_id === null) {
 82:             return null;
 83:         }
 84: 
 85:         return ShippingRate::query()
 86:             ->join('shipping_zones', 'shipping_zones.id', '=', 'shipping_rates.shipping_zone_id')
 87:             ->join('shipping_zone_cities', 'shipping_zone_cities.shipping_zone_id', '=', 'shipping_zones.id')
 88:             ->where('shipping_rates.shipping_company_id', $companyId)
 89:             ->where('shipping_zone_cities.city_id', $order->city_id)
 90:             ->where('shipping_zones.is_active', true)
 91:             ->orderBy('shipping_rates.id')
 92:             ->select('shipping_rates.*')
 93:             ->first();
 94:     }
 95: 
 96:     // تسعيرة العميل الموحدة في ShippingQuoteService (بلا تبعية دائرية)
 97: 
 98:     private function generateAwb(ShippingCompany $company): string
 99:     {
100:         do {
101:             $awb = Str::upper($company->code).'-'.Str::upper(Str::random(10));
102:         } while (Shipment::query()->where('awb_number', $awb)->exists());
103: 
104:         return $awb;
105:     }
106: } 1: <?php
