 5: namespace App\Http\Controllers\Api\V1\Store;
 6: 
 7: use App\Http\Controllers\Controller;
 8: use App\Http\Requests\Store\Cart\AddCartItemRequest;
 9: use App\Http\Requests\Store\Cart\ApplyCouponRequest;
10: use App\Http\Requests\Store\Cart\UpdateCartItemRequest;
11: use App\Models\Cart;
12: use App\Models\Customer;
13: use App\Services\CartService;
14: use App\Services\CouponService;
15: use Illuminate\Http\JsonResponse;
16: use Illuminate\Http\Request;
17: 
18: /**
19:  * سلة المتجر — تعمل للزائر (هيدر X-Cart-Session) وللعميل المسجل (Bearer)
20:  * بنفس النقاط؛ الهوية تُحسم داخل CartService.
21:  */
22: class CartController extends Controller
23: {
24:     public function __construct(
25:         private readonly CartService $carts,
26:         private readonly CouponService $coupons,
27:     ) {}
28: 
29:     public function index(Request $request): JsonResponse
30:     {
31:         // قراءة فقط: لا يُحفظ صف سلة لمجرد العرض (M3)
32:         [$customer, $cart] = $this->currentCart($request, create: false);
33: 
34:         return response()->json(['data' => $this->carts->present($cart, $customer)]);
35:     }
36: 
37:     public function store(AddCartItemRequest $request): JsonResponse
38:     {
39:         [$customer, $cart] = $this->currentCart($request);
40:         $cart = $this->carts->addItem($cart, $customer, (int) $request->validated()['product_variant_id'], (float) $request->validated()['qty']);
41: 
42:         return response()->json(['data' => $this->carts->present($cart, $customer)]);
43:     }
44: 
45:     public function update(UpdateCartItemRequest $request, int $item): JsonResponse
46:     {
47:         [$customer, $cart] = $this->currentCart($request);
48:         $cartItem = $cart->items()->findOrFail($item);
49:         $cart = $this->carts->updateItemQty($cart, $customer, (int) $cartItem->product_variant_id, (float) $request->validated()['qty']);
50: 
51:         return response()->json(['data' => $this->carts->present($cart, $customer)]);
52:     }
53: 
54:     public function destroy(Request $request, int $item): JsonResponse
55:     {
56:         [$customer, $cart] = $this->currentCart($request);
57:         $cartItem = $cart->items()->findOrFail($item);
58:         $cart = $this->carts->removeItem($cart, (int) $cartItem->product_variant_id);
59: 
60:         return response()->json(['data' => $this->carts->present($cart, $customer)]);
61:     }
62: 
63:     public function removeCoupon(Request $request): JsonResponse
64:     {
65:         [$customer, $cart] = $this->currentCart($request);
66:         $cart->update(['coupon_id' => null]);
67: 
68:         return response()->json(['data' => $this->carts->present($cart->refresh(), $customer)]);
69:     }
70: 
71:     public function applyCoupon(ApplyCouponRequest $request): JsonResponse
72:     {
73:         [$customer, $cart] = $this->currentCart($request);
74:         $totals = $this->carts->totals($cart, $customer);
75:         $discount = $this->coupons->validateAndApply($cart, (string) $request->validated()['code'], $totals['items_total'], $customer);
76: 
77:         return response()->json(['data' => [
78:             'cart' => $this->carts->present($cart->fresh(), $customer),
79:             'coupon_discount' => $discount,
80:         ]]);
81:     }
82: 
83:     /** @return array{0: ?Customer, 1: Cart} */
84:     private function currentCart(Request $request, bool $create = true): array
85:     {
86:         $user = auth('sanctum')->user();
87:         $customer = $user instanceof Customer ? $user : null;
88:         $cart = $this->carts->resolveCart($customer, $request->header('X-Cart-Session'), $create);
89: 
90:         return [$customer, $cart];
91:     }
92: } 1: <?php
