  5: namespace App\Services;
  6: 
  7: use App\Enums\ProductStatus;
  8: use App\Exceptions\BusinessException;
  9: use App\Models\Cart;
 10: use App\Models\Customer;
 11: use App\Models\ProductVariant;
 12: use Illuminate\Database\UniqueConstraintViolationException;
 13: use Illuminate\Support\Facades\DB;
 14: use Illuminate\Support\Str;
 15: 
 16: /**
 17:  * سلة التسوق للزائر والعميل المسجل.
 18:  * - الزائر: سلة مربوطة بـ cart_token (يُرسل في هيدر X-Cart-Session).
 19:  * - العميل: سلة مربوطة بحسابه؛ وعند تسجيل الدخول تُدمج سلة الزائر فيها.
 20:  * الأسعار دائمًا لحظية من PricingService (لا تُخزّن في السلة أبدًا).
 21:  */
 22: class CartService
 23: {
 24:     public function __construct(
 25:         protected PricingService $pricing,
 26:         protected StoreCatalogService $catalog,
 27:         protected CouponService $coupons,
 28:     ) {}
 29: 
 30:     /**
 31:      * سلة الزائر/العميل الحالية.
 32:      * - التوكن غير الـ UUID يُتجاهل تمامًا (M2)؛ وتوكن أي سلة جديدة
 33:      *   يُولّد على الخادم دائمًا (Cart::booted) ولا يُقبل مقترح العميل.
 34:      * - بوضع القراءة ($create=false) لا يُحفظ أي صف: تُرجع سلة فارغة
 35:      *   افتراضية حتى لا تملأ الزواحف جدول carts (M3).
 36:      * لو وُجدت سلة زائر بالتوكن وعميل مسجل، تُدمج فيها أولًا.
 37:      */
 38:     public function resolveCart(?Customer $customer, ?string $guestToken, bool $create = true): Cart
 39:     {
 40:         $guestToken = $guestToken !== null && Str::isUuid($guestToken) ? $guestToken : null;
 41: 
 42:         if ($customer !== null) {
 43:             $cart = $create
 44:                 ? $this->accountCart($customer)
 45:                 : (Cart::query()->where('customer_id', $customer->id)->first() ?? new Cart(['customer_id' => $customer->id]));
 46:             if ($create && $guestToken !== null && $guestToken !== $cart->cart_token) {
 47:                 $this->mergeGuestCart($customer, $guestToken);
 48:                 $cart = $cart->fresh();
 49:             }
 50: 
 51:             return $cart->loadMissing('items');
 52:         }
 53: 
 54:         $cart = $guestToken !== null
 55:             ? Cart::query()->where('cart_token', $guestToken)->whereNull('customer_id')->first()
 56:             : null;
 57:         if ($cart !== null) {
 58:             return $cart->loadMissing('items');
 59:         }
 60: 
 61:         return ($create ? Cart::create([]) : new Cart)->loadMissing('items');
 62:     }
 63: 
 64:     /** سلة حساب العميل الوحيدة — القيد الفريد على customer_id يحسم السباق (M6). */
 65:     private function accountCart(Customer $customer): Cart
 66:     {
 67:         try {
 68:             return Cart::query()->firstOrCreate(['customer_id' => $customer->id]);
 69:         } catch (UniqueConstraintViolationException) {
 70:             return Cart::query()->where('customer_id', $customer->id)->firstOrFail();
 71:         }
 72:     }
 73: 
 74:     /** دمج سلة زائر (بالتوكن) في سلة حساب العميل — تُستدعى عند تسجيل الدخول. */
 75:     public function mergeGuestCart(Customer $customer, ?string $guestToken): void
 76:     {
 77:         $guestToken = $guestToken !== null && Str::isUuid($guestToken) ? $guestToken : null;
 78:         if ($guestToken === null) {
 79:             return;
 80:         }
 81: 
 82:         // كل الدمج داخل transaction واحدة وسلة الزائر مقفولة: طلبات متوازية
 83:         // بعد تسجيل الدخول بنفس التوكن لا تضاعف الكميات (M6)
 84:         DB::transaction(function () use ($customer, $guestToken): void {
 85:             $guest = Cart::query()->where('cart_token', $guestToken)->whereNull('customer_id')
 86:                 ->lockForUpdate()->first();
 87:             if ($guest === null) {
 88:                 return;
 89:             }
 90:             if (! $guest->items()->exists()) {
 91:                 $guest->delete();
 92: 
 93:                 return;
 94:             }
 95: 
 96:             $account = $this->accountCart($customer);
 97:             foreach ($guest->items as $item) {
 98:                 $existing = $account->items()->where('product_variant_id', $item->product_variant_id)->first();
 99:                 if ($existing !== null) {
100:                     $existing->update(['qty' => (float) $existing->qty + (float) $item->qty]);
101:                 } else {
102:                     $account->items()->create([
103:                         'product_variant_id' => $item->product_variant_id,
104:                         'qty' => $item->qty,
105:                     ]);
106:                 }
107:             }
108:             if ($account->coupon_id === null && $guest->coupon_id !== null) {
109:                 $account->update(['coupon_id' => $guest->coupon_id]);
110:             }
111:             $guest->items()->delete();
112:             $guest->delete();
113:         });
114:     }
115: 
116:     public function addItem(Cart $cart, ?Customer $customer, int $variantId, float $qty): Cart
117:     {
118:         $variant = $this->purchasableVariant($variantId);
119:         $existing = $cart->items()->where('product_variant_id', $variantId)->first();
120:         $targetQty = ($existing !== null ? (float) $existing->qty : 0) + $qty;
121:         $this->assertAvailable($variantId, $targetQty);
122:         $this->assertPriced($variant, $customer, $targetQty);
123: 
124:         if ($existing !== null) {
125:             // زيادة ذرّية بدل قراءة ثم كتابة (L2)
126:             $existing->increment('qty', $qty);
127:         } else {
128:             $cart->items()->create(['product_variant_id' => $variantId, 'qty' => $qty]);
129:         }
130: 
131:         return $cart->fresh('items');
132:     }
133: 
134:     public function updateItemQty(Cart $cart, ?Customer $customer, int $variantId, float $qty): Cart
135:     {
136:         if ($qty <= 0) {
137:             return $this->removeItem($cart, $variantId);
138:         }
139:         $variant = $this->purchasableVariant($variantId);
140:         $this->assertAvailable($variantId, $qty);
141:         $this->assertPriced($variant, $customer, $qty);
142: 
143:         $cart->items()->updateOrCreate(
144:             ['product_variant_id' => $variantId],
145:             ['qty' => $qty],
146:         );
147: 
148:         return $cart->fresh('items');
149:     }
150: 
151:     public function removeItem(Cart $cart, int $variantId): Cart
152:     {
153:         $cart->items()->where('product_variant_id', $variantId)->delete();
154: 
155:         return $cart->fresh('items');
156:     }
157: 
158:     /**
159:      * بنود السلة بأسعار لحظية من PricingService.
160:      * بند غير قابل للتسعير يرجع بـ unit_price = null (العرض يتجاوزه،
161:      * وإتمام الشراء يرفضه — يتحقق المستدعي).
162:      *
163:      * @return array<int, array{variant: ProductVariant, qty: float, unit_price: float|null, base_price: float|null, line_discount: float, line_total: float}>
164:      */
165:     public function pricedLines(Cart $cart, ?Customer $customer): array
166:     {
167:         $cart->loadMissing('items.variant.product');
168:         $lines = [];
169:         foreach ($cart->items as $item) {
170:             $variant = $item->variant;
171:             $qty = (float) $item->qty;
172:             try {
173:                 $resolved = $this->pricing->resolve($variant, $customer, $qty);
174:                 $unit = (float) $resolved['unit_price'];
175:                 $base = (float) $resolved['base_price'];
176:                 $lines[] = [
177:                     'item_id' => $item->id,
178:                     'variant' => $variant,
179:                     'qty' => $qty,
180:                     'unit_price' => $unit,
181:                     'base_price' => $base,
182:                     'line_discount' => round(($base - $unit) * $qty, 2),
183:                     'line_total' => round($unit * $qty, 2),
184:                 ];
185:             } catch (BusinessException) {
186:                 $lines[] = [
187:                     'item_id' => $item->id,
188:                     'variant' => $variant,
189:                     'qty' => $qty,
190:                     'unit_price' => null,
191:                     'base_price' => null,
192:                     'line_discount' => 0.0,
193:                     'line_total' => 0.0,
194:                 ];
195:             }
196:         }
197: 
198:         return $lines;
199:     }
200: 
201:     /**
202:      * ملخص السلة المالي بالأسعار اللحظية.
203:      *
204:      * @return array{subtotal: float, pricing_discount: float, items_total: float, coupon_discount: float, total: float, coupon_code: string|null}
205:      */
206:     /**
207:      * @param  array<int, array<string, mixed>>|null  $lines  بنود محسوبة مسبقًا
208:      *                                                        لتجنب إعادة التسعير (M15)
209:      */
210:     public function totals(Cart $cart, ?Customer $customer, ?array $lines = null): array
211:     {
212:         $lines ??= $this->pricedLines($cart, $customer);
213:         $subtotal = 0.0;
214:         $pricingDiscount = 0.0;
215:         $itemsTotal = 0.0;
216:         foreach ($lines as $line) {
217:             if ($line['unit_price'] === null) {
218:                 continue;
219:             }
220:             // كل سطر يُقرَّب أولًا ثم تُجمع القيم المقرّبة (M17)
221:             $subtotal += round((float) $line['base_price'] * $line['qty'], 2);
222:             $pricingDiscount += $line['line_discount'];
223:             $itemsTotal += $line['line_total'];
224:         }
225: 
226:         $couponDiscount = 0.0;
227:         $couponCode = null;
228:         if ($cart->coupon_id !== null && $itemsTotal > 0) {
229:             try {
230:                 $coupon = $this->coupons->redeemableById((int) $cart->coupon_id, $itemsTotal, $customer);
231:                 $couponDiscount = $this->coupons->discountFor($coupon, $itemsTotal);
232:                 $couponCode = $coupon->code;
233:             } catch (BusinessException) {
234:                 // كوبون لم يعد صالحًا: يُعرض الملخص بدونه (إتمام الشراء سيعيد التحقق)
235:             }
236:         }
237: 
238:         return [
239:             'subtotal' => round($subtotal, 2),
240:             'pricing_discount' => round($pricingDiscount, 2),
241:             'items_total' => round($itemsTotal, 2),
242:             'coupon_discount' => $couponDiscount,
243:             'total' => round($itemsTotal - $couponDiscount, 2),
244:             'coupon_code' => $couponCode,
245:         ];
246:     }
247: 
248:     /**
249:      * إعادة التحقق من قابلية البيع لكل بند لحظة الشراء بشكل مجمّع (M14):
250:      * متغير معطّل أو منتج غير منشور/محذوف ناعمًا بعد الإضافة يوقف الطلب.
251:      *
252:      * @param  array<int, array{variant: ProductVariant, qty: float}>  $lines
253:      */
254:     public function assertLinesPurchasable(array $lines): void
255:     {
256:         $ids = array_map(fn (array $line): int => (int) $line['variant']->id, $lines);
257:         $variants = ProductVariant::query()->with('product')
258:             ->whereIn('id', $ids)->get()->keyBy('id');
259:         foreach ($lines as $line) {
260:             $variant = $variants->get($line['variant']->id) ?? $line['variant'];
261:             if (! $variant->is_active || $variant->product === null
262:                 || $variant->product->status !== ProductStatus::Published || $variant->product->trashed()) {
263:                 throw new BusinessException("الصنف ({$variant->sku}) لم يعد متاحًا للبيع؛ أزله من السلة وأعد المحاولة.");
264:             }
265:         }
266:     }
267: 
268:     /**
269:      * إعادة التحقق من توفر بنود مُسعّرة لحظة الشراء.
270:      *
271:      * @param  array<int, array{variant: ProductVariant, qty: float}>  $lines
272:      */
273:     public function assertLinesAvailable(array $lines): void
274:     {
275:         $ids = array_map(fn (array $line): int => (int) $line['variant']->id, $lines);
276:         $map = $this->catalog->availabilityMap($ids);
277:         foreach ($lines as $line) {
278:             if (($map[$line['variant']->id] ?? 0) < $line['qty']) {
279:                 throw new BusinessException("الكمية المتاحة من الصنف ({$line['variant']->sku}) لم تعد كافية لإتمام الطلب.");
280:             }
281:         }
282:     }
283: 
284:     /**
285:      * تمثيل السلة للعرض: البنود بأسعار ومتاح لحظي + الملخص المالي.
286:      *
287:      * @return array<string, mixed>
288:      */
289:     public function present(Cart $cart, ?Customer $customer): array
290:     {
291:         $lines = $this->pricedLines($cart, $customer);
292:         $ids = array_map(fn (array $line): int => (int) $line['variant']->id, $lines);
293:         $availability = $this->catalog->availabilityMap($ids);
294: 
295:         $items = [];
296:         foreach ($lines as $line) {
297:             $variant = $line['variant'];
298:             $items[] = [
299:                 'id' => $line['item_id'],
300:                 'product_variant_id' => $variant->id,
301:                 'product_id' => $variant->product_id,
302:                 'product_name' => $variant->product?->name_ar,
303:                 'sku' => $variant->sku,
304:                 'qty' => $line['qty'],
305:                 'unit_price' => $line['unit_price'],
306:                 'base_price' => $line['base_price'],
307:                 'line_discount' => $line['line_discount'],
308:                 'line_total' => $line['line_total'],
309:                 'available' => $availability[$variant->id] ?? 0,
310:                 'priced' => $line['unit_price'] !== null,
311:             ];
312:         }
313: 
314:         return [
315:             'id' => $cart->id,
316:             'cart_token' => $cart->cart_token,
317:             'customer_id' => $cart->customer_id,
318:             'items' => $items,
319:             'totals' => $this->totals($cart, $customer, $lines),
320:         ];
321:     }
