323:     private function purchasableVariant(int $variantId): ProductVariant
324:     {
325:         $variant = ProductVariant::query()->with('product')->find($variantId);
326:         if ($variant === null || ! $variant->is_active || $variant->product === null
327:             || $variant->product->status !== ProductStatus::Published || $variant->product->trashed()) {
328:             throw new BusinessException('الصنف غير متاح للشراء.');
329:         }
330: 
331:         return $variant;
332:     }
333: 
334:     private function assertAvailable(int $variantId, float $qty): void
335:     {
336:         $available = $this->catalog->availabilityMap([$variantId])[$variantId] ?? 0;
337:         if ($available < $qty) {
338:             throw new BusinessException('الكمية المطلوبة غير متاحة حاليًا لهذا الصنف.');
339:         }
340:     }
341: 
342:     private function assertPriced(ProductVariant $variant, ?Customer $customer, float $qty): void
343:     {
344:         $this->pricing->resolve($variant, $customer, $qty); // يرمي BusinessException عند غياب السعر
345:     }
