  7: use App\Enums\OrderStatus;
  8: use App\Models\Order;
  9: use App\Models\WebhookLog;
 10: use Illuminate\Support\Facades\DB;
 11: use Illuminate\Support\Facades\Log;
 12: use Throwable;
 13: 
 14: /**
 15:  * معالجة ويب هوك بوابات الدفع:
 16:  * تسجيل أولًا ← تحقق HMAC ← معالجة ذرّية داخل transaction بقفل استشاري
 17:  * على (provider, event) لمنع المعالجة المكررة المتزامنة (H4) ←
 18:  * التحقق من المبلغ والعملة مقابل إجمالي الطلب (H5) ← تحديث حالة الدفع
 19:  * وتأكيد الطلب تلقائيًا عبر OrderService عند النجاح.
 20:  */
 21: class PaymentWebhookService
 22: {
 23:     private const SUCCESS = ['paid', 'success', 'successful', 'succeeded', 'captured', 'completed', 'approved'];
 24: 
 25:     private const FAILED = ['failed', 'voided', 'declined', 'error', 'cancelled', 'canceled'];
 26: 
 27:     public function __construct(
 28:         protected WebhookSignatureVerifier $verifier,
 29:         protected OrderService $orders,
 30:     ) {}
 31: 
 32:     /** @return array{http: int, body: array<string, mixed>} */
 33:     public function handle(string $gateway, array $payload, string $rawBody, ?string $signature, ?string $ip): array
 34:     {
 35:         $provider = 'payment:'.$gateway;
 36:         // مفتاح الحدث: معرّف البوابة، وإلا بصمة جسم الطلب (H4)
 37:         $eventId = $this->extractEventId($payload) ?? 'sha256:'.hash('sha256', $rawBody);
 38: 
 39:         // حد حجم الجسم أولًا — الرفض بسجل مختصر بلا حمولة (M4)
 40:         if (strlen($rawBody) > 262144) {
 41:             $this->slimLog($provider, $eventId, 'rejected', 'payload too large', $ip);
 42: 
 43:             return ['http' => 413, 'body' => ['received' => false, 'message' => 'payload too large']];
 44:         }
 45: 
 46:         $config = config("webhooks.payment.{$gateway}");
 47:         if (! is_array($config)) {
 48:             $this->slimLog($provider, $eventId, 'failed', 'بوابة دفع غير معروفة', $ip);
 49: 
 50:             return ['http' => 404, 'body' => ['received' => false, 'message' => 'unknown gateway']];
 51:         }
 52: 
 53:         // التحقق من التوقيع قبل تخزين الحمولة: محاولات مجهولة لا تملأ
 54:         // webhook_logs.payload — تُسجل مختصرة فقط (M4)
 55:         if (! $this->verifier->verify($config['secret'] ?? null, $rawBody, $signature)) {
 56:             $this->slimLog($provider, $eventId, 'invalid_signature', null, $ip);
 57: 
 58:             return ['http' => 403, 'body' => ['received' => false, 'message' => 'invalid signature']];
 59:         }
 60: 
 61:         $log = $this->startLog($provider, $eventId, $payload, $ip);
 62:         $log->update(['signature_valid' => true]);
 63: 
 64:         return DB::transaction(function () use ($gateway, $provider, $eventId, $payload, $log, $config): array {
 65:             // قفل استشاري على مفتاح الحدث: نسختان متزامنتان من نفس الحدث تتسلسلان هنا
 66:             DB::statement('SELECT pg_advisory_xact_lock(hashtext(?))', [$provider.':'.$eventId]);
 67: 
 68:             if ($this->alreadyProcessed($provider, $log)) {
 69:                 $log->update(['status' => 'duplicate']);
 70: 
 71:                 return ['http' => 200, 'body' => ['received' => true, 'duplicate' => true]];
 72:             }
 73: 
 74:             $orderNumber = $this->extractOrderNumber($payload);
 75:             $order = $orderNumber !== null
 76:                 ? Order::query()->where('order_number', $orderNumber)->lockForUpdate()->first()
 77:                 : null;
 78:             if ($order === null) {
 79:                 $log->update(['status' => 'failed', 'error' => 'طلب غير موجود: '.($orderNumber ?? '—')]);
 80: 
 81:                 return ['http' => 200, 'body' => ['received' => false, 'message' => 'order not found']];
 82:             }
 83: 
 84:             $outcome = $this->outcome($payload);
 85:             if ($outcome === 'ignored' || $outcome === 'pending') {
 86:                 $log->update([
 87:                     'status' => 'ignored',
 88:                     'error' => $outcome === 'pending' ? 'معاملة معلقة لدى البوابة (pending)' : 'حالة دفع غير معروفة في الحمولة',
 89:                 ]);
 90: 
 91:                 return ['http' => 200, 'body' => ['received' => true, 'ignored' => true]];
 92:             }
 93: 
 94:             // التحقق من المبلغ والعملة قبل أي تغيير (H5)
 95:             if ($outcome === 'paid' && ! $this->amountMatches($payload, $order, $config)) {
 96:                 $log->update(['status' => 'failed', 'error' => 'amount mismatch']);
 97: 
 98:                 return ['http' => 200, 'body' => ['received' => false, 'message' => 'amount mismatch']];
 99:             }
100: 
101:             $note = null;
102:             if ($outcome === 'paid') {
103:                 if ($order->status === OrderStatus::Cancelled) {
104:                     // مال قُبض على طلب ملغي: يُثبت الدفع ويُعلَّم للاسترداد، ولا يُحيى الطلب
105:                     $order->update(['payment_status' => 'paid', 'requires_refund' => true]);
106:                     $note = 'دفع ناجح على طلب ملغي — يحتاج استردادًا';
107:                 } else {
108:                     $order->update(['payment_status' => 'paid']);
109:                     if ($order->status === OrderStatus::Pending) {
110:                         try {
111:                             $this->orders->changeStatus($order, OrderStatus::Confirmed, null, "تأكيد تلقائي بعد نجاح الدفع عبر {$gateway}");
112:                         } catch (Throwable $e) {
113:                             // «دُفع ولم يُؤكَّد» حالة تشغيلية خطيرة: تنبيه سجل +
114:                             // علامة ظاهرة في شاشة الطلب بدل دفنها في الويب هوك (M19)
115:                             Log::warning('Payment captured but order auto-confirm failed.', [
116:                                 'order_id' => $order->id,
117:                                 'order_number' => $order->order_number,
118:                                 'gateway' => $gateway,
119:                                 'exception' => $e->getMessage(),
120:                             ]);
121:                             $order->update(['needs_attention' => true]);
122:                             $note = 'تم الدفع لكن تأكيد الطلب فشل: '.$e->getMessage();
123:                         }
124:                     }
125:                 }
126:             } elseif ($outcome === 'failed') {
127:                 if ($order->payment_status === 'paid') {
128:                     // حدث فشل متأخر بعد نجاح: لا رجوع من paid إلى failed
129:                     $log->update(['status' => 'ignored', 'error' => 'حدث فشل متأخر بعد دفع ناجح — يُتجاهل']);
130: 
131:                     return ['http' => 200, 'body' => ['received' => true, 'ignored' => true]];
132:                 }
133:                 $order->update(['payment_status' => 'failed']);
134:             } else { // refunded
135:                 $order->update(['payment_status' => 'refunded']);
136:                 if (in_array($order->status, [OrderStatus::Shipped, OrderStatus::Delivered], true)) {
137:                     $note = 'استرداد على طلب مشحون/مُسلَّم — يحتاج مراجعة';
138:                 }
139:             }
140: 
141:             $log->update(['status' => 'processed', 'error' => $note]);
142: 
143:             return ['http' => 200, 'body' => ['received' => true]];
144:         });
145:     }
146: 
147:     private function outcome(array $payload): string
148:     {
149:         // معاملة معلقة (Paymob: success=false مع pending=true) ليست فشلًا
150:         $pending = data_get($payload, 'obj.pending') ?? data_get($payload, 'data.pending') ?? data_get($payload, 'pending');
151:         if ($pending === true) {
152:             return 'pending';
153:         }
154: 
155:         $successFlag = data_get($payload, 'obj.success') ?? data_get($payload, 'data.success') ?? data_get($payload, 'success');
156:         if (is_bool($successFlag)) {
157:             return $successFlag ? 'paid' : 'failed';
158:         }
159: 
160:         $status = strtolower((string) ($this->firstValue($payload, ['status', 'payment_status', 'data.status', 'obj.status', 'state']) ?? ''));
161:         if (in_array($status, self::SUCCESS, true)) {
162:             return 'paid';
163:         }
164:         if ($status === 'refunded' || $status === 'refund') {
165:             return 'refunded';
166:         }
167:         if (in_array($status, self::FAILED, true)) {
168:             return 'failed';
169:         }
170: 
171:         return 'ignored';
172:     }
173: 
174:     /**
175:      * مقارنة مبلغ الحدث بإجمالي الطلب وعملته. إن لم يحمل الحدث مبلغًا
176:      * يُقبل (بعض البوابات لا ترسله) — وإن حمله واختلف يُرفض.
177:      *
178:      * @param  array<string, mixed>  $config
179:      */
180:     private function amountMatches(array $payload, Order $order, array $config): bool
181:     {
182:         $currency = $this->firstValue($payload, ['currency', 'data.currency', 'obj.currency', 'obj.order.currency']);
183:         if ($currency !== null && strtoupper((string) $currency) !== 'EGP') {
184:             return false;
185:         }
186: 
187:         $amount = $this->firstValue($payload, ['amount', 'data.amount', 'obj.amount', 'obj.order.amount']);
188:         $divisor = (float) ($config['amount_divisor'] ?? 1);
189:         if ($amount === null) {
190:             $cents = $this->firstValue($payload, ['amount_cents', 'data.amount_cents', 'obj.amount_cents', 'obj.order.amount_cents']);
191:             if ($cents !== null) {
192:                 $amount = $cents;
193:                 $divisor = 100.0;
194:             }
195:         }
196:         if ($amount === null) {
197:             return true;
198:         }
199: 
200:         return abs(round(((float) $amount) / $divisor, 2) - (float) $order->grand_total) < 0.01;
201:     }
202: 
203:     private function extractOrderNumber(array $payload): ?string
204:     {
205:         $value = $this->firstValue($payload, [
206:             'order_number', 'merchant_order_id', 'data.order_number',
207:             'obj.order.merchant_order_id', 'obj.merchant_order_id', 'metadata.order_number',
208:         ]);
209: 
210:         return $value !== null ? (string) $value : null;
211:     }
212: 
213:     private function extractEventId(array $payload): ?string
214:     {
215:         $value = $this->firstValue($payload, ['event_id', 'transaction_id', 'obj.id', 'data.id', 'data.transaction_id']);
216: 
217:         return $value !== null ? (string) $value : null;
218:     }
219: 
220:     /** @param array<int, string> $keys */
221:     private function firstValue(array $payload, array $keys): mixed
222:     {
223:         foreach ($keys as $key) {
224:             $value = data_get($payload, $key);
225:             if ($value !== null && $value !== '') {
226:                 return $value;
227:             }
228:         }
229: 
230:         return null;
231:     }
232: 
233:     private function startLog(string $provider, string $eventId, array $payload, ?string $ip): WebhookLog
234:     {
235:         return WebhookLog::create([
236:             'provider' => $provider,
237:             'event_id' => $eventId,
238:             'payload' => $payload,
239:             'status' => 'received',
240:             'ip_address' => $ip,
241:         ]);
242:     }
243: 
244:     /** سجل مختصر للطلبات المرفوضة قبل التحقق — بلا تخزين للحمولة (M4). */
245:     private function slimLog(string $provider, string $eventId, string $status, ?string $error, ?string $ip): void
246:     {
247:         WebhookLog::create([
248:             'provider' => $provider,
249:             'event_id' => $eventId,
250:             'payload' => null,
251:             'signature_valid' => false,
252:             'status' => $status,
253:             'error' => $error,
254:             'ip_address' => $ip,
255:         ]);
256:     }
257: 
258:     private function alreadyProcessed(string $provider, WebhookLog $current): bool
259:     {
260:         return WebhookLog::query()
261:             ->where('provider', $provider)
262:             ->where('event_id', $current->event_id)
263:             ->where('id', '!=', $current->id)
264:             ->where('status', 'processed')
265:             ->exists();
266:     }
