 42:     /** رتبة التقدم في سلسلة التسليم — التراجع في الرتبة يعني حدثًا متأخرًا. */
 43:     private const RANK = [
 44:         'created' => 0,
 45:         'picked_up' => 1,
 46:         'in_transit' => 2,
 47:         'out_for_delivery' => 3,
 48:         'delivered' => 4,
 49:         'returned' => 4,
 50:     ];
 51: 
 52:     public function __construct(
 53:         protected WebhookSignatureVerifier $verifier,
 54:         protected OrderService $orders,
 55:     ) {}
 56: 
 57:     /** @return array{http: int, body: array<string, mixed>} */
 58:     public function handle(string $companyCode, array $payload, string $rawBody, ?string $signature, ?string $ip): array
 59:     {
 60:         $provider = 'shipping:'.$companyCode;
 61:         $eventId = $this->effectiveEventId($payload, $rawBody);
 62: 
 63:         if (strlen($rawBody) > 262144) {
 64:             $this->slimLog($provider, $eventId, 'rejected', 'payload too large', $ip);
 65: 
 66:             return ['http' => 413, 'body' => ['received' => false, 'message' => 'payload too large']];
 67:         }
 68: 
 69:         $company = ShippingCompany::query()->where('code', $companyCode)->first();
 70:         if ($company === null) {
 71:             $this->slimLog($provider, $eventId, 'failed', 'شركة شحن غير معروفة', $ip);
 72: 
 73:             return ['http' => 404, 'body' => ['received' => false, 'message' => 'unknown company']];
 74:         }
 75: 
 76:         // سر التوقيع: webhook_secret الخاص بالشركة فقط — لا رجوع لمفتاح API
 77:         // ولا لسر افتراضي مشترك (M10)، والتحقق قبل تخزين الحمولة (M4)
 78:         $credentials = $company->api_credentials ?? [];
 79:         $secret = $credentials['webhook_secret'] ?? null;
 80:         if (! is_string($secret) || $secret === '' || ! $this->verifier->verify($secret, $rawBody, $signature)) {
 81:             $this->slimLog($provider, $eventId, 'invalid_signature',
 82:                 (! is_string($secret) || $secret === '') ? 'لا يوجد webhook_secret مضبوط للشركة' : null, $ip);
 83: 
 84:             return ['http' => 403, 'body' => ['received' => false, 'message' => 'invalid signature']];
 85:         }
 86: 
 87:         $log = $this->startLog($provider, $eventId, $payload, $ip);
 88:         $log->update(['signature_valid' => true]);
 89: 
 90:         return DB::transaction(function () use ($provider, $payload, $log, $company): array {
 91:             DB::statement('SELECT pg_advisory_xact_lock(hashtext(?))', [$provider.':'.$log->event_id]);
 92: 
 93:             if ($this->alreadyProcessed($provider, $log)) {
 94:                 $log->update(['status' => 'duplicate']);
 95: 
 96:                 return ['http' => 200, 'body' => ['received' => true, 'duplicate' => true]];
 97:             }
 98: 
 99:             $awb = $this->firstValue($payload, ['awb_number', 'tracking_number', 'awb', 'data.awb_number', 'data.tracking_number']);
100:             $shipment = $awb !== null
101:                 ? Shipment::query()->where('awb_number', (string) $awb)->where('shipping_company_id', $company->id)->lockForUpdate()->first()
102:                 : null;
103:             if ($shipment === null) {
104:                 $log->update(['status' => 'failed', 'error' => 'بوليصة غير موجودة: '.($awb !== null ? (string) $awb : '—')]);
105: 
106:                 return ['http' => 200, 'body' => ['received' => false, 'message' => 'shipment not found']];
107:             }
108: 
109:             $status = $this->mapStatus($payload);
110:             if ($status === null) {
111:                 $log->update(['status' => 'ignored', 'error' => 'حالة شحن غير معروفة في الحمولة']);
112: 
113:                 return ['http' => 200, 'body' => ['received' => true, 'ignored' => true]];
114:             }
115: 
116:             // ترتيب الحالات: لا تراجع من حالة نهائية ولا في سلسلة التقدم (H6)
117:             if (! $this->transitionAllowed($shipment->status, $status)) {
118:                 $log->update(['status' => 'ignored', 'error' => "حدث متأخر/متراجع: {$shipment->status->value} ← {$status->value}"]);
119: 
120:                 return ['http' => 200, 'body' => ['received' => true, 'ignored' => true]];
121:             }
122: 
123:             $shipment->update(['status' => $status]);
124: 
125:             $note = null;
126:             if ($status === ShipmentStatus::Returned) {
127:                 // مرتجع الشحن ينعكس على الطلب عبر بوابة الحالة (M11)
128:                 $order = $shipment->order;
129:                 if ($order !== null && in_array($order->status, [OrderStatus::Shipped, OrderStatus::Delivered], true)) {
130:                     try {
131:                         $this->orders->changeStatus($order, OrderStatus::Returned, null, 'أرجعت شركة الشحن البوليصة');
132:                     } catch (Throwable $e) {
133:                         $note = 'تم إرجاع البوليصة لكن تحويل الطلب فشل: '.$e->getMessage();
134:                     }
135:                 }
136:             }
137:             if ($status === ShipmentStatus::Delivered) {
138:                 $order = $shipment->order;
139:                 if ($order !== null && $order->status === OrderStatus::Shipped) {
140:                     try {
141:                         $this->orders->changeStatus($order, OrderStatus::Delivered, null, 'تم التسليم — إشعار شركة الشحن');
142:                     } catch (Throwable $e) {
143:                         $note = 'تم تسليم البوليصة لكن تحويل الطلب فشل: '.$e->getMessage();
144:                     }
145:                     // تحصيل COD يُثبت فقط مع انتقال فعلي Shipped → Delivered
146:                     // وبنفس المعاملة (M11): حدث على ملغي/مرتجع لا يثبت دفعًا
147:                     $order->refresh();
148:                     if ($order->status === OrderStatus::Delivered
149:                         && $order->payment_method === 'cod' && $order->payment_status !== 'paid') {
150:                         $order->update(['payment_status' => 'paid']);
151:                     }
152:                 }
153:             }
154: 
155:             $log->update(['status' => 'processed', 'error' => $note]);
156: 
157:             return ['http' => 200, 'body' => ['received' => true]];
158:         });
159:     }
160: 
161:     private function transitionAllowed(ShipmentStatus $current, ShipmentStatus $new): bool
162:     {
163:         if ($current === $new) {
164:             return true;
165:         }
166:         // الحالات النهائية لا تتحرك
167:         if (in_array($current, [ShipmentStatus::Delivered, ShipmentStatus::Returned], true)) {
168:             return false;
169:         }
170:         // الفشل قد يحدث في أي مرحلة، ومن الفشل يمكن استئناف التقدم (إعادة محاولة التسليم)
171:         if ($new === ShipmentStatus::Failed || $current === ShipmentStatus::Failed) {
172:             return true;
173:         }
174:         // الإرجاع مسموح من أي مرحلة غير نهائية
175:         if ($new === ShipmentStatus::Returned) {
176:             return true;
177:         }
178: 
179:         return (self::RANK[$new->value] ?? 0) >= (self::RANK[$current->value] ?? 0);
180:     }
181: 
182:     /**
183:      * مفتاح حدث فعّال: معرّف حدث حقيقي فقط (id الشحنة ثابت في كل تحديثاتها
184:      * فلا يصلح مفتاحًا)، وإلا مركّب awb|status|timestamp، وإلا بصمة الجسم.
185:      */
186:     private function effectiveEventId(array $payload, string $rawBody): string
187:     {
188:         $eventId = $this->firstValue($payload, ['event_id', 'eventId', 'data.event_id']);
189:         if ($eventId !== null) {
190:             return (string) $eventId;
191:         }
192: 
193:         $awb = $this->firstValue($payload, ['awb_number', 'tracking_number', 'awb', 'data.awb_number']);
194:         $status = $this->firstValue($payload, ['status', 'state', 'shipment_status', 'data.status']);
195:         $timestamp = $this->firstValue($payload, ['timestamp', 'occurred_at', 'updated_at', 'data.timestamp', 'data.updated_at']);
196:         if ($awb !== null && $status !== null && $timestamp !== null) {
197:             return $awb.'|'.$status.'|'.$timestamp;
198:         }
199: 
200:         return 'sha256:'.hash('sha256', $rawBody);
201:     }
202: 
203:     private function mapStatus(array $payload): ?ShipmentStatus
204:     {
205:         $raw = $this->firstValue($payload, ['status', 'state', 'shipment_status', 'data.status', 'data.state']);
206:         if ($raw === null) {
207:             return null;
208:         }
209:         $key = str_replace([' ', '-'], '_', strtolower(trim((string) $raw)));
210: 
211:         return self::STATUS_MAP[$key] ?? null;
212:     }
213: 
214:     /** @param array<int, string> $keys */
215:     private function firstValue(array $payload, array $keys): mixed
216:     {
217:         foreach ($keys as $key) {
218:             $value = data_get($payload, $key);
219:             if ($value !== null && $value !== '') {
220:                 return $value;
221:             }
222:         }
223: 
224:         return null;
225:     }
226: 
227:     private function startLog(string $provider, string $eventId, array $payload, ?string $ip): WebhookLog
228:     {
229:         return WebhookLog::create([
230:             'provider' => $provider,
231:             'event_id' => $eventId,
232:             'payload' => $payload,
233:             'status' => 'received',
234:             'ip_address' => $ip,
235:         ]);
236:     }
237: 
238:     /** سجل مختصر للطلبات المرفوضة قبل التحقق — بلا تخزين للحمولة (M4). */
239:     private function slimLog(string $provider, string $eventId, string $status, ?string $error, ?string $ip): void
240:     {
241:         WebhookLog::create([
242:             'provider' => $provider,
243:             'event_id' => $eventId,
244:             'payload' => null,
245:             'signature_valid' => false,
246:             'status' => $status,
247:             'error' => $error,
248:             'ip_address' => $ip,
249:         ]);
250:     }
251: 
252:     private function alreadyProcessed(string $provider, WebhookLog $current): bool
253:     {
254:         return WebhookLog::query()
255:             ->where('provider', $provider)
256:             ->where('event_id', $current->event_id)
257:             ->where('id', '!=', $current->id)
258:             ->where('status', 'processed')
259:             ->exists();
260:     }
