 23: /**
 24:  * خدمات الطلب.
 25:  * - createFromCart: تحويل سلة إلى طلب بلقطات أسعار من PricingService،
 26:  *   وخصم الكوبون، وشحن المدينة، وضريبة الإعدادات، ثم إفراغ السلة.
 27:  * - changeStatus: بوابة تغيير الحالة الوحيدة — تتحقق من آلة الحالات،
 28:  *   وتسجل التغيير في order_status_histories، وتدير آثار المخزون:
 29:  *   confirmed ← حجز وتوزيع، shipped ← فك حجز + بيع فعلي،
 30:  *   cancelled (من confirmed/processing) ← فك حجز.
 31:  */
 32: class OrderService
 33: {
 34:     /** الانتقالات المسموحة بين حالات الطلب. */
 35:     private const TRANSITIONS = [
 36:         'pending' => ['confirmed', 'cancelled'],
 37:         'confirmed' => ['processing', 'shipped', 'cancelled'],
 38:         'processing' => ['shipped', 'cancelled'],
 39:         'shipped' => ['delivered', 'returned'],
 40:         'delivered' => ['returned'],
 41:         'cancelled' => [],
 42:         'returned' => [],
 43:     ];
 44: 
 45:     public function __construct(
 46:         protected OrderAllocationService $allocationService,
 47:         protected CartService $cartService,
 48:         protected CouponService $couponService,
 49:         protected SettingService $settings,
 50:         protected InventoryService $inventoryService,
 51:         protected ShippingQuoteService $shippingQuote,
 52:     ) {}
 53: 
 54:     /**
 55:      * تحويل سلة إلى طلب جديد بحالة pending.
 56:      *
 57:      * @param  array{recipient_name?: string|null, recipient_phone?: string|null, recipient_email?: string|null, city_id?: int|null, shipping_address_line?: string|null, shipping_notes?: string|null, payment_method?: string|null, channel?: string}  $data
 58:      */
 59:     public function createFromCart(Cart $cart, array $data, ?Customer $customer = null): Order
 60:     {
 61:         return DB::transaction(function () use ($cart, $data, $customer): Order {
 62:             // قفل صف السلة وقراءة بنودها طازجة: طلب متزامن ثانٍ ينتظر
 63:             // ثم يجد السلة فارغة بدل إنشاء طلب مكرر (H2)
 64:             $cart = Cart::query()->whereKey($cart->id)->lockForUpdate()->firstOrFail();
 65:             $cart->load('items');
 66:             if ($cart->items->isEmpty()) {
 67:                 throw new BusinessException('السلة فارغة؛ لا يمكن إنشاء طلب.');
 68:             }
 69: 
 70:             $lines = $this->cartService->pricedLines($cart, $customer);
 71:             foreach ($lines as $line) {
 72:                 if ($line['unit_price'] === null) {
 73:                     throw new BusinessException("الصنف ({$line['variant']->sku}) غير مُسعَّر؛ لا يمكن إتمام الطلب.");
 74:                 }
 75:             }
 76: 
 77:             // إعادة التحقق من التوفر وقابلية البيع لحظة الشراء (M14):
 78:             // صنف عُطّل أو منتج أُلغي نشره/حُذف بعد الإضافة لا يُشترى
 79:             $this->cartService->assertLinesAvailable($lines);
 80:             $this->cartService->assertLinesPurchasable($lines);
 81:             $totals = $this->cartService->totals($cart, $customer, $lines);
 82:             $subtotal = $totals['subtotal'];
 83:             $pricingDiscount = $totals['pricing_discount'];
 84: 
 85:             // الكوبون: إعادة تحقق صارمة عند الشراء (يشمل حد العميل الواحد)
 86:             $couponDiscount = 0.0;
 87:             $couponId = null;
 88:             $couponCode = null;
 89:             $coupon = null;
 90:             if ($cart->coupon_id !== null) {
 91:                 // قفل صف الكوبون حتى نهاية المعاملة: التحقق من الحدود والعدّ
 92:                 // وتسجيل الاستخدام تصبح ذرّية أمام عمليات شراء متزامنة (H3)
 93:                 Coupon::query()->whereKey((int) $cart->coupon_id)->lockForUpdate()->first();
 94:                 try {
 95:                     $coupon = $this->couponService->redeemableById(
 96:                         (int) $cart->coupon_id,
 97:                         $totals['items_total'],
 98:                         $customer,
 99:                         $customer === null ? ($data['recipient_phone'] ?? null) : null,
100:                     );
101:                 } catch (BusinessException $e) {
102:                     // رمز مميز حتى تعرض الواجهة زر إزالة الكوبون (H8)
103:                     throw new BusinessException($e->getMessage(), $e->errors, $e->status, 'coupon_invalid');
104:                 }
105:                 $couponDiscount = $this->couponService->discountFor($coupon, $totals['items_total']);
106:                 $couponId = $coupon->id;
107:                 $couponCode = $coupon->code;
108:             }
109:             $discountAmount = round($pricingDiscount + $couponDiscount, 2);
110: 
111:             // الشحن من تسعيرة المناطق الموحدة (M12): سعر المنطقة/الشركة
112:             // وحدها المجاني ورسوم COD — ورجوع لسعر المدينة عند غياب سعر.
113:             // كوبون الشحن المجاني يعفي من تكلفة الشحن (لا من رسوم COD)
114:             $city = null;
115:             $shippingCost = 0.0;
116:             $codFee = 0.0;
117:             if (! empty($data['city_id'])) {
118:                 $city = City::query()->where('is_active', true)->find((int) $data['city_id']);
119:                 if ($city === null) {
120:                     throw new BusinessException('مدينة التوصيل غير متاحة.');
121:                 }
122:                 $quote = $this->shippingQuote->quoteForCity(
123:                     $city->id,
124:                     $totals['items_total'] - $couponDiscount,
125:                     ($data['payment_method'] ?? 'cod') === 'cod',
126:                 );
127:                 $shippingCost = $quote['cost'];
128:                 $codFee = $quote['cod_fee'];
129:             }
130:             $waivedShipping = 0.0;
131:             if ($coupon !== null && $coupon->type === 'free_shipping' && $shippingCost > 0) {
132:                 $waivedShipping = $shippingCost;
133:                 $shippingCost = 0.0;
134:             }
135: 
136:             // الضريبة من الإعدادات (مفعّلة وغير مشمولة في الأسعار فقط)
137:             $taxAmount = 0.0;
138:             $taxRate = 0.0;
139:             if (filter_var($this->settings->get('tax_enabled', false), FILTER_VALIDATE_BOOLEAN)
140:                 && ! filter_var($this->settings->get('prices_include_tax', false), FILTER_VALIDATE_BOOLEAN)) {
141:                 $taxRate = (float) $this->settings->get('default_tax_rate', 0);
142:                 $taxAmount = round(($subtotal - $discountAmount) * $taxRate / 100, 2);
143:             }
144: 
145:             $grandTotal = round(($subtotal - $discountAmount) + $shippingCost + $codFee + $taxAmount, 2);
146: 
147:             $order = Order::create([
148:                 'order_number' => $this->settings->generateNextNumber('order'),
149:                 'channel' => $data['channel'] ?? 'store',
150:                 'customer_id' => $customer?->id,
151:                 'guest_name' => $data['recipient_name'] ?? $customer?->name,
152:                 'guest_phone' => $data['recipient_phone'] ?? $customer?->phone,
153:                 'guest_email' => $data['recipient_email'] ?? $customer?->email,
154:                 'city_id' => $city?->id,
155:                 'shipping_address_line' => $data['shipping_address_line'] ?? null,
156:                 'shipping_notes' => $data['shipping_notes'] ?? null,
157:                 'status' => OrderStatus::Pending,
158:                 'payment_method' => $data['payment_method'] ?? 'cod',
159:                 'payment_status' => 'unpaid',
160:                 'subtotal' => $subtotal,
161:                 'discount_amount' => $discountAmount,
162:                 'coupon_id' => $couponId,
163:                 'coupon_code' => $couponCode,
164:                 'shipping_cost' => $shippingCost,
165:                 'cod_fee' => $codFee,
166:                 'tax_amount' => $taxAmount,
167:                 'grand_total' => $grandTotal,
168:             ]);
169: 
170:             // بنود الطلب بلقطات الاسم والـ SKU والسعر + توزيع الضريبة وحصة
171:             // الكوبون تناسبيًا حتى يساوي مجموع خصومات البنود خصم الطلب (M17)
172:             $remainingTax = $taxAmount;
173:             $remainingCoupon = $couponDiscount;
174:             $lastIndex = count($lines) - 1;
175:             foreach ($lines as $i => $line) {
176:                 $lineTax = $i === $lastIndex
177:                     ? $remainingTax
178:                     : round($taxAmount * ($line['line_total'] / max($totals['items_total'], 0.01)), 2);
179:                 $remainingTax = round($remainingTax - $lineTax, 2);
180:                 $couponShare = $i === $lastIndex
181:                     ? $remainingCoupon
182:                     : round($couponDiscount * ($line['line_total'] / max($totals['items_total'], 0.01)), 2);
183:                 $remainingCoupon = round($remainingCoupon - $couponShare, 2);
184: 
185:                 $order->items()->create([
186:                     'product_variant_id' => $line['variant']->id,
187:                     'product_name_snapshot' => $line['variant']->product?->name_ar ?? '',
188:                     'sku_snapshot' => $line['variant']->sku,
189:                     'qty' => $line['qty'],
190:                     'unit_price' => $line['unit_price'],
191:                     'discount_amount' => round($line['line_discount'] + max($couponShare, 0), 2),
192:                     'tax_amount' => max($lineTax, 0),
193:                     'line_total' => $line['line_total'],
194:                 ]);
195:             }
196: 
197:             // تسجيل استخدام الكوبون فعليًا (خصم البضاعة أو الشحن المُعفى)
198:             if ($coupon !== null) {
199:                 $this->couponService->recordUsage(
200:                     $coupon,
201:                     $order,
202:                     $customer,
203:                     $coupon->type === 'free_shipping' ? $waivedShipping : $couponDiscount,
204:                 );
205:             }
206: 
207:             // أول سجل حالة: إنشاء الطلب
208:             $order->statusHistories()->create([
209:                 'from_status' => null,
210:                 'to_status' => OrderStatus::Pending,
211:                 'changed_by_type' => $customer?->getMorphClass(),
212:                 'changed_by_id' => $customer?->getKey(),
213:                 'notes' => 'تم إنشاء الطلب من السلة',
214:             ]);
215: 
216:             // إفراغ السلة بعد تحويلها لطلب
217:             $cart->items()->delete();
218:             $cart->update(['coupon_id' => null]);
219: 
220:             return $order->fresh(['items', 'statusHistories']);
221:         });
222:     }
223: 
224:     public function changeStatus(Order $order, OrderStatus|string $toStatus, ?Model $actor = null, ?string $notes = null): Order
225:     {
226:         $to = $toStatus instanceof OrderStatus ? $toStatus : OrderStatus::from($toStatus);
227: 
228:         return DB::transaction(function () use ($order, $to, $actor, $notes): Order {
229:             // إعادة قراءة الطلب بقفل صف: النسخة الممرَّرة قد تكون قديمة،
230:             // وكل الانتقالات على نفس الطلب يجب أن تتسلسل (C1)
231:             $order = Order::query()->lockForUpdate()->findOrFail($order->id);
232:             $from = $order->status;
233:             if ($from === $to) {
234:                 return $order;
235:             }
236: 
237:             if (! in_array($to->value, self::TRANSITIONS[$from->value] ?? [], true)) {
238:                 throw new BusinessException("انتقال حالة غير مسموح: من ({$from->value}) إلى ({$to->value}).");
239:             }
240: 
241:             $actorId = $this->inventoryActorId($actor);
242: 
243:             // آثار المخزون بحسب الانتقال
244:             $extraNote = null;
245:             if ($to === OrderStatus::Shipped) {
246:                 $this->shipOrder($order, $actorId);
247:             } elseif ($to === OrderStatus::Cancelled
248:                 && in_array($from, [OrderStatus::Confirmed, OrderStatus::Processing], true)) {
249:                 $this->releaseReservations($order, $actorId, 'إلغاء الطلب');
250:             } elseif ($to === OrderStatus::Returned
251:                 && in_array($from, [OrderStatus::Shipped, OrderStatus::Delivered], true)) {
252:                 // إعادة البضاعة المشحونة للمخزون بحركات sale_return (M13)
253:                 if (! $this->returnSalesToStock($order, $actorId)) {
254:                     $extraNote = 'لا توجد حركات بيع مسجلة؛ يتطلب المرتجع استلامًا يدويًا في المستودع.';
255:                 }
256:             }
257: 
258:             if ($to === OrderStatus::Cancelled) {
259:                 // عكس استخدام الكوبون حتى لا يُحرم العميل منه بإلغاء (M13)
260:                 $this->reverseCouponUsage($order);
261:                 if ($order->payment_status === 'paid') {
262:                     $order->update(['requires_refund' => true]);
263:                 }
264:             }
265: 
266:             $order->update(['status' => $to]);
267: 
268:             $order->statusHistories()->create([
269:                 'from_status' => $from,
270:                 'to_status' => $to,
271:                 'changed_by_type' => $actor?->getMorphClass(),
272:                 'changed_by_id' => $actor?->getKey(),
273:                 'notes' => trim(($notes ?? '').($extraNote !== null ? ' — '.$extraNote : '')) ?: $notes,
274:             ]);
275: 
276:             if ($to === OrderStatus::Confirmed && $order->allocated_branch_id === null) {
277:                 $this->allocationService->allocate($order, performedBy: $actorId);
278:             }
279: 
280:             return $order->fresh(['items', 'statusHistories']);
281:         });
282:     }
283: 
284:     /**
285:      * الشحن: لكل حركة حجز — فك الحجز من reserved وخصم فعلي sale من on_hand
286:      * على نفس صف الرصيد، وزيادة عدّاد مبيعات المنتج.
287:      */
288:     private function shipOrder(Order $order, ?int $actorId): void
289:     {
290:         $reservations = $this->reserveMovements($order);
291:         if ($reservations->isEmpty()) {
292:             throw new BusinessException('لا توجد حجوزات مخزون لهذا الطلب؛ لا يمكن الشحن قبل التأكيد والتوزيع.');
293:         }
294: 
295:         foreach ($reservations as $movement) {
296:             $base = [
297:                 'product_variant_id' => $movement->product_variant_id,
298:                 'branch_id' => $movement->branch_id,
299:                 'location_id' => $movement->location_id,
300:                 'reference_type' => Order::class,
301:                 'reference_id' => $order->id,
302:                 'created_by' => $actorId,
303:             ];
304:             $this->inventoryService->recordMovement([...$base,
305:                 'type' => StockMovementType::ReleaseReserve,
306:                 'affected_bucket' => StockBucket::Reserved,
307:                 'quantity' => -1 * (float) $movement->quantity,
308:                 'notes' => "فك حجز عند شحن الطلب {$order->order_number}",
309:             ]);
310:             $this->inventoryService->recordMovement([...$base,
311:                 'type' => StockMovementType::Sale,
312:                 'affected_bucket' => StockBucket::OnHand,
313:                 'quantity' => -1 * (float) $movement->quantity,
314:                 'notes' => "بيع عند شحن الطلب {$order->order_number}",
315:             ]);
316:         }
317: 
318:         foreach ($order->items as $item) {
319:             $item->variant?->product?->increment('sales_count', (int) round((float) $item->qty));
320:         }
321:     }
322: 
323:     /** إلغاء طلب مُحجوز: فك كل حجوزاته فتعود الكميات متاحة للبيع. */
324:     private function releaseReservations(Order $order, ?int $actorId, string $reason): void
325:     {
326:         foreach ($this->reserveMovements($order) as $movement) {
327:             $this->inventoryService->recordMovement([
328:                 'product_variant_id' => $movement->product_variant_id,
329:                 'branch_id' => $movement->branch_id,
330:                 'location_id' => $movement->location_id,
331:                 'type' => StockMovementType::ReleaseReserve,
332:                 'affected_bucket' => StockBucket::Reserved,
333:                 'quantity' => -1 * (float) $movement->quantity,
334:                 'reference_type' => Order::class,
335:                 'reference_id' => $order->id,
336:                 'created_by' => $actorId,
337:                 'notes' => "{$reason} {$order->order_number}",
338:             ]);
339:         }
340:     }
341: 
342:     /**
343:      * إعادة بضاعة طلب مشحون/مُسلَّم إلى المخزون: لكل حركة بيع حركة
344:      * sale_return معاكسة على نفس الرصيد، وتنقيص عدّاد المبيعات (M13).
345:      * ترجع false إذا لم توجد حركات بيع (يحتاج استلامًا يدويًا).
346:      */
347:     private function returnSalesToStock(Order $order, ?int $actorId): bool
348:     {
349:         $sales = StockMovement::query()
350:             ->where('reference_type', $order->getMorphClass())
351:             ->where('reference_id', $order->id)
352:             ->where('type', StockMovementType::Sale)
353:             ->orderBy('id')
354:             ->get();
355:         if ($sales->isEmpty()) {
356:             return false;
357:         }
358: 
359:         foreach ($sales as $movement) {
360:             $this->inventoryService->recordMovement([
361:                 'product_variant_id' => $movement->product_variant_id,
362:                 'branch_id' => $movement->branch_id,
363:                 'location_id' => $movement->location_id,
364:                 'type' => StockMovementType::SaleReturn,
365:                 'affected_bucket' => StockBucket::OnHand,
366:                 'quantity' => -1 * (float) $movement->quantity,
367:                 'reference_type' => Order::class,
368:                 'reference_id' => $order->id,
369:                 'created_by' => $actorId,
370:                 'notes' => "مرتجع مبيعات للطلب {$order->order_number}",
371:             ]);
372:         }
373: 
374:         foreach ($order->items as $item) {
375:             $product = $item->variant?->product;
376:             if ($product !== null) {
377:                 $product->update(['sales_count' => max(0, (int) $product->sales_count - (int) round((float) $item->qty))]);
378:             }
379:         }
380: 
381:         return true;
382:     }
383: 
384:     /** عكس تسجيل استخدام الكوبون عند إلغاء الطلب: حذف السجل وإنقاص العدّاد (M13). */
385:     private function reverseCouponUsage(Order $order): void
386:     {
387:         foreach (CouponUsage::query()->where('order_id', $order->id)->get() as $usage) {
388:             Coupon::query()->whereKey($usage->coupon_id)->where('used_count', '>', 0)->decrement('used_count');
389:             $usage->delete();
390:         }
391:     }
392: 
393:     /** حركات الحجز الأصلية للطلب من الدفتر (مصدر الحقيقة لمواضع الحجز ومواقعه). */
394:     private function reserveMovements(Order $order): Collection
395:     {
396:         return StockMovement::query()
397:             ->where('reference_type', $order->getMorphClass())
398:             ->where('reference_id', $order->id)
399:             ->where('type', StockMovementType::Reserve)
400:             ->orderBy('id')
401:             ->get();
402:     }
