413:     private function inventoryActorId(?Model $actor): ?int
414:     {
415:         if ($actor instanceof User) {
416:             return (int) $actor->getKey();
417:         }
418: 
419:         if (! self::$systemActorResolved) {
420:             self::$systemActorResolved = true;
421:             $systemId = User::query()
422:                 ->where('email', (string) config('orders.system_user_email', 'system@alfarid.local'))
423:                 ->value('id');
424:             self::$systemActorId = $systemId !== null ? (int) $systemId : null;
425:         }
426:         if (self::$systemActorId !== null) {
427:             return self::$systemActorId;
428:         }
429: 
430:         // رجوع احتياطي إن لم تُزرع هجرة مستخدم النظام بعد
431:         $adminId = User::query()
432:             ->whereHas('roles', fn ($q) => $q->where('name', 'Super Admin'))
433:             ->orderBy('id')
434:             ->value('id');
435: 
436:         return $adminId !== null ? (int) $adminId : (auth()->user() instanceof User ? (int) auth()->id() : null);
437:     }
